window.CHAPTER_DATA = window.CHAPTER_DATA || {};
window.CHAPTER_DATA[1] = "<section class=\"chapter-section\" id=\"c11e-ch1\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">1</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Hornbill (Prose) &bull; Chapter 1</div>\n      <h2>The Portrait of a Lady</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 7 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #f8fafc, #eff6ff); border:1px solid #cbd5e1; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#1e293b; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#4338ca\" stroke-width=\"2\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"/><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z\"/></svg>\n      Thematic Concept: Three Phases of the Relationship\n    </h3>\n    <svg viewBox=\"0 0 800 220\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"20\" y=\"30\" width=\"230\" height=\"150\" rx=\"10\" fill=\"#ffffff\" stroke=\"#4338ca\" stroke-width=\"2\"/>\n      <text x=\"135\" y=\"65\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"bold\" fill=\"#4338ca\">Phase 1: Village Life</text>\n      <text x=\"135\" y=\"95\" text-anchor=\"middle\" font-size=\"12\" fill=\"#475569\">Complete Companionship</text>\n      <text x=\"135\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" fill=\"#64748b\">• Woke him up & dressed him</text>\n      <text x=\"135\" y=\"140\" text-anchor=\"middle\" font-size=\"11\" fill=\"#64748b\">• School attached to temple</text>\n      <text x=\"135\" y=\"160\" text-anchor=\"middle\" font-size=\"11\" fill=\"#64748b\">• Fed street village dogs</text>\n\n      <path d=\"M 255 105 L 285 105\" stroke=\"#94a3b8\" stroke-width=\"3\" marker-end=\"url(#arrow)\"/>\n\n      <rect x=\"285\" y=\"30\" width=\"230\" height=\"150\" rx=\"10\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"400\" y=\"65\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"bold\" fill=\"#0284c7\">Phase 2: City Life</text>\n      <text x=\"400\" y=\"95\" text-anchor=\"middle\" font-size=\"12\" fill=\"#475569\">The Turning Point</text>\n      <text x=\"400\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" fill=\"#64748b\">• Motor bus to English school</text>\n      <text x=\"400\" y=\"140\" text-anchor=\"middle\" font-size=\"11\" fill=\"#64748b\">• No scriptures, hated music</text>\n      <text x=\"400\" y=\"160\" text-anchor=\"middle\" font-size=\"11\" fill=\"#64748b\">• Fed courtyard sparrows</text>\n\n      <path d=\"M 520 105 L 550 105\" stroke=\"#94a3b8\" stroke-width=\"3\"/>\n\n      <rect x=\"550\" y=\"30\" width=\"230\" height=\"150\" rx=\"10\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"665\" y=\"65\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"bold\" fill=\"#059669\">Phase 3: University Life</text>\n      <text x=\"665\" y=\"95\" text-anchor=\"middle\" font-size=\"12\" fill=\"#475569\">Silent Seclusion</text>\n      <text x=\"665\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" fill=\"#64748b\">• Given a separate room</text>\n      <text x=\"665\" y=\"140\" text-anchor=\"middle\" font-size=\"11\" fill=\"#64748b\">• Friendship link snapped</text>\n      <text x=\"665\" y=\"160\" text-anchor=\"middle\" font-size=\"11\" fill=\"#64748b\">• Spinning wheel & rosary prayers</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Understanding the Text & Talking About the Text</div>\n\n  <!-- c11e-ch1-q1 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch1-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch1-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Mention the three phases of the author’s relationship with his grandmother before he left the country to study abroad.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The author, Khushwant Singh, details three distinct, emotional phases in his relationship with his grandmother over the course of his early life:</p>\n      <ol style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>Phase 1: Childhood in the Village (Intimate Companionship):</strong> The author lived alone with his grandmother while his parents settled in the city. She was his sole caregiver, waking him up, bathing him, plastering his slate, reciting morning prayers in a monotonous sing-song, and escorting him to the temple school. They were inseparable companions, and on their return, she fed stale chapattis to village dogs.</li>\n        <li><strong>Phase 2: Boyhood in the City (The Turning Point):</strong> When called to the city by his parents, their bond weakened. Though they still shared a room, the grandmother no longer accompanied him to school as he traveled by an English motor bus. She could neither assist him with his Western science curriculum (law of gravity, Archimedes' principle) nor approve of the lack of scriptural education and the inclusion of music. They saw significantly less of each other.</li>\n        <li><strong>Phase 3: University Life (Snapped Friendship & Seclusion):</strong> When the author enrolled in university, he was allocated a room of his own. The last physical link of their companionship was formally severed. The grandmother stoically accepted her seclusion, spending her days at the spinning wheel, reciting prayers on her rosary, and feeding hundreds of sparrows in the courtyard.</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Phase 1: Village life with daily care, temple school & dog feeding described</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Phase 2: City life turning point with English school & lack of religious teaching</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Phase 3: University separate room, snapped friendship link & quiet seclusion</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch1-q2 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch1-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch1-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Mention three reasons why the author’s grandmother was disturbed when he started going to the city school.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The grandmother was deeply agitated and distressed when the author began attending the city English school because:</p>\n      <ol style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>Inability to Assist in Studies:</strong> The curriculum was taught in English and covered Western science (Archimedes' principle, gravity, the earth being round). Since she did not know English or modern science, she felt completely sidelined and unable to guide him.</li>\n        <li><strong>Absence of Moral and Religious Instruction:</strong> She was distressed to learn that there was no teaching about God, holy scriptures, or spiritual values in the city school curriculum, which she considered the core foundation of true education.</li>\n        <li><strong>Aversion to Music Lessons:</strong> When he announced he was receiving music lessons, she was appalled. To her traditional mindset, music had \"lewd associations\"—she believed it was the exclusive monopoly of harlots and beggars and had no place in the upbringing of respectable gentlefolk. Her disapproving silence conveyed her deep displeasure.</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Reason 1: Could not help with English/Western science lessons</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reason 2: Absence of religious teachings and scriptures in the syllabus</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reason 3: Strict orthodox belief that music was indecent for gentlefolk</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch1-q3 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch1-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch1-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Mention three ways in which the author’s grandmother spent her days after he grew up.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>After the author grew up and was assigned a separate room at university, the grandmother spent her days in three fixed routines:</p>\n      <ol style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>Spinning Wheel:</strong> From sunrise to sunset, she sat by her spinning wheel spinning thread, rarely pausing to speak to anyone in the household.</li>\n        <li><strong>Continuous Prayer and Rosary:</strong> Her lips constantly moved in an inaudible, silent prayer while her fingers ceaselessly told the beads of her rosary.</li>\n        <li><strong>Feeding the Courtyard Sparrows:</strong> Only in the afternoon did she relax for half an hour to feed sparrows in the verandah. She broke bread into little crumbs, and hundreds of birds perched on her legs, shoulders, and head. She smiled gently but never shooed them away; this was consistently the happiest half-hour of her day.</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Spinning wheel from sunrise to sunset in quiet solitary labour</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Constant silent prayers while telling the beads of her rosary</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Afternoon ritual of feeding crumbs to hundreds of fearless sparrows</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch1-q4 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch1-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch1-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Mention the odd way in which the author’s grandmother behaved just before she died.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Just before her death, the grandmother exhibited strange and uncharacteristic behavior:</p>\n      <ul style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>Sudden Break in Lifelong Habit:</strong> On the evening the author returned from abroad, she did not pray—a first in her entire life. Instead, she collected women from the neighborhood, acquired an old dilapidated drum, and thudded its sagging skin for hours, singing celebratory songs of warriors returning home.</li>\n        <li><strong>Pre-monition of Impending End:</strong> The next morning she was taken ill with a mild fever. Although the doctor assured the family it would pass, she declared with absolute conviction that her end was near.</li>\n        <li><strong>Refusal to Converse:</strong> She stated that since she had omitted her prayers in the last chapter of her life, she would not waste another moment talking to her family.</li>\n        <li><strong>Peaceful Departure in Prayer:</strong> Ignoring all familial protests, she lay peacefully in bed, reciting prayers and telling her beads until her lips stopped moving and the rosary fell from her lifeless fingers.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Unusual evening celebration beating drum and singing homecoming songs</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Firm proclamation that her end was near despite medical reassurance</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Refusal to talk, devoting every last breath to silent prayer and beads</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch1-q5 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch1-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch1-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Mention the way in which the sparrows expressed their sorrow when the author’s grandmother died.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The sparrows paid an extraordinary, solemn tribute to the departed grandmother, displaying emotional empathy that transcended animal instinct:</p>\n      <ul style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>Silent Gathering:</strong> When the grandmother's shroud-wrapped body lay on the verandah floor, thousands of sparrows flew in and sat scattered all over the courtyard.</li>\n        <li><strong>Total Absence of Chirping:</strong> Unlike their usual lively chatter and chirruping, there was complete, mournful silence across the courtyard.</li>\n        <li><strong>Disregard for Food:</strong> Feeling pity, the author’s mother threw small pieces of bread crumbs to them, exactly as the grandmother used to. The sparrows took absolutely no notice of the bread, proving they had not assembled for food but to mourn their human benefactor.</li>\n        <li><strong>Quiet Departure:</strong> As soon as the corpse was carried out for cremation, the sparrows flew away silently. The next morning, the sweeper swept the untouched bread crumbs into the dustbin.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Thousands of sparrows assembled in complete, eerie silence</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Refusal to touch breadcrumbs thrown by the author’s mother</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Quiet, solemn dispersal once the grandmother’s bier was carried away</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch1-q6 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch1-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch1-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        The author’s grandmother was a religious person. What are the different ways in which we come to know this?\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Khushwant Singh’s narrative paints the portrait of an intensely pious, spiritual woman whose existence was anchored in religious faith:</p>\n      <ol style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>Inaudible Prayers & Rosary:</strong> Her lips were perpetually moving in an inaudible, meditative prayer, and her hands were continuously occupied telling the beads of her rosary.</li>\n        <li><strong>Temple Visits in the Village:</strong> She chose to accompany the author to the village school every morning specifically because the school was attached to a temple, allowing her to sit inside and read holy scriptures while he studied the alphabet.</li>\n        <li><strong>Morning Hymns:</strong> While washing and dressing the author, she recited morning hymns in a monotonous sing-song voice, hoping he would absorb them by heart.</li>\n        <li><strong>Discontent with Secular Curriculum:</strong> In the city, her primary resentment against the modern school was its lack of religious and moral instruction.</li>\n        <li><strong>Compassion for God's Creatures:</strong> Feeding stale chapattis to village dogs and bread crumbs to sparrows was an extension of her religious duty and dharmic compassion.</li>\n        <li><strong>Devotion at the Hour of Death:</strong> On her deathbed, she refused to waste precious minutes in conversation, dedicating her final moments purely to God until the rosary slipped from her fingers.</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Continuous telling of rosary beads and silent prayer recitation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Temple routine, reading scriptures and teaching morning hymns</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Philosophical distress over lack of God/scriptures in modern schools</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Prioritizing communion with God over family conversation on deathbed</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch1-q7 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch1-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch1-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        Describe the mutual love and bond between the grandmother and the author. Did the emotional distance change their feelings for each other?\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The relationship between the author and his grandmother is one of profound, unspoken tenderness, mutual respect, and emotional steadfastness:</p>\n      <ul style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>Deep Childhood Affection:</strong> In early childhood, the grandmother was the author's world. She tended to his physical and emotional needs with unconditional maternal warmth, fostering deep mutual trust.</li>\n        <li><strong>Acceptance of Changing Circumstances:</strong> As the author grew into adolescence and adulthood, physical distance inevitably grew—first through city schooling, then university separation, and eventually five years of foreign study. However, the grandmother never harbored bitterness, never demanded attention, and gracefully accepted her seclusion without guilt-tripping the author.</li>\n        <li><strong>Unfading Emotional Bond:</strong> When the author left for abroad, she kissed his forehead silently at the railway station—a moist touch the author cherished as possibly the last physical imprint of their love. When he returned five years later, she clasped him in her arms, whispering her prayers.</li>\n        <li><strong>Conclusion:</strong> Although modernization and adulthood created physical distance, their underlying emotional connection remained pristine and untarnished until the very end.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Early childhood companionship and tender nurturing described</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dignified acceptance of inevitable separation due to higher studies</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Railway station farewell kiss and affectionate homecoming reunion</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Concluding analysis confirming enduring mutual love despite physical distance</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <a href=\"../ncert-solutions-class-11-english.html\" class=\"ch-nav-btn prev\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; text-decoration:none; color:#334155;\">← Class 11 English Hub</a>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 2 (We're Not Afraid to Die... if We Can All Be Together) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[2] = "<section class=\"chapter-section\" id=\"c11e-ch2\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">2</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Hornbill (Prose) &bull; Chapter 2</div>\n      <h2>We're Not Afraid to Die... if We Can All Be Together</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 6 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #f0fdf4, #e0f2fe); border:1px solid #cbd5e1; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#1e293b; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#0284c7\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polygon points=\"16.24 7.76 14.12 14.12 7.76 16.24 9.88 9.88 16.24 7.76\"/></svg>\n      Voyage Map & Crisis Timeline: Wavewalker’s Heroic Journey\n    </h3>\n    <svg viewBox=\"0 0 800 200\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"20\" y=\"25\" width=\"220\" height=\"150\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"130\" y=\"55\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#0284c7\">Stage 1: July 1976</text>\n      <text x=\"130\" y=\"80\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Plymouth to Cape Town</text>\n      <text x=\"130\" y=\"105\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• 105,000 km pleasant run</text>\n      <text x=\"130\" y=\"125\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Took crewmen Larry & Herb</text>\n      <text x=\"130\" y=\"145\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Southern Indian Ocean entry</text>\n\n      <path d=\"M 245 100 L 275 100\" stroke=\"#94a3b8\" stroke-width=\"3\"/>\n\n      <rect x=\"275\" y=\"25\" width=\"240\" height=\"150\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"395\" y=\"55\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#dc2626\">Stage 2: Jan 2 - 4 Crisis</text>\n      <text x=\"395\" y=\"80\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Gigantic Waves & Blast</text>\n      <text x=\"395\" y=\"105\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Torrential explosion on deck</text>\n      <text x=\"395\" y=\"125\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Broken ribs, flooded cabins</text>\n      <text x=\"395\" y=\"145\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Continuous manual pumping</text>\n\n      <path d=\"M 520 100 L 550 100\" stroke=\"#94a3b8\" stroke-width=\"3\"/>\n\n      <rect x=\"550\" y=\"25\" width=\"230\" height=\"150\" rx=\"8\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n      <text x=\"665\" y=\"55\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#16a34a\">Stage 3: Jan 6 Relief</text>\n      <text x=\"665\" y=\"80\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Arrival at Ile Amsterdam</text>\n      <text x=\"665\" y=\"105\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Pinprick volcanic island</text>\n      <text x=\"665\" y=\"125\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• French scientific base</text>\n      <text x=\"665\" y=\"145\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• 28 inhabitants welcome them</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Understanding the Text & Talking About the Text</div>\n\n  <!-- c11e-ch2-q1 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch2-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch2-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        List the steps taken by the captain: (i) to protect the ship when rough weather began, (ii) to check the flooding of water in the ship.\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The captain took critical precautionary and damage-control measures:</p>\n      <h4 style=\"color:#0284c7; margin-top:8px;\">(i) Steps to protect the ship when rough weather began:</h4>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Slowing the Boat:</strong> Dropped the storm jib and looped a heavy mooring rope across the stern to reduce the vessel's speed.</li>\n        <li><strong>Double-Lashing Everything:</strong> Securely fastened all gear and equipment on deck to prevent shifting.</li>\n        <li><strong>Life-Raft Drill:</strong> Attached lifelines to life rafts, donned waterproof oilskins, and strapped on life jackets.</li>\n      </ul>\n      <h4 style=\"color:#0284c7; margin-top:10px;\">(ii) Steps to check the flooding of water in the ship:</h4>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Waterproofing Gaping Holes:</strong> Stretched canvas and secured waterproof hatch covers across the shattered starboard side to deflect incoming waves over the side.</li>\n        <li><strong>Managing Hand Pumps:</strong> When primary hand pumps clogged with debris and the main electric pump short-circuited under water, the captain located an auxiliary electric pump under the chartroom floor and connected it to an out-pipe.</li>\n        <li><strong>Continuous Pumping:</strong> Larry, Herb, and the narrator pumped out water relentlessly for 36 hours until the water level was reduced to a few centimeters.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Steps to protect ship: storm jib, mooring rope, lifelines and life jackets</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Steps to check flooding: canvas hatch covers, spare electric pump, non-stop pumping</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch2-q2 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch2-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch2-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Describe the mental condition of the voyagers on 4 and 5 January.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The emotional and psychological condition of the voyagers fluctuated dramatically across these 48 hours:</p>\n      <ul style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>January 4 (Temporary Respite & Fragile Hope):</strong> After 36 hours of continuous pumping, they managed to keep pace with the incoming seawater. They consumed their first meal in nearly two days (corned beef and cracker biscuits). The atmosphere was tinged with exhausted relief, although the captain knew the boat’s structural frame was critically weakened.</li>\n        <li><strong>January 5 (Grim Despair & Impending Doom):</strong> Their respite was short-lived. By 4 p.m., black storm clouds gathered again, winds whipped up to 40 knots, and waves towered menacingly. When the narrator went in to comfort the children, Jonathan asked if they were going to die. The children’s bravery deeply moved him, but when night fell, water seeped in steadily through broken timber. By dawn, the situation was utterly hopeless, and the adult voyagers sat holding hands, convinced that their end was very near.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Jan 4: First meal, temporary relief after 36 hours pumping</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Jan 5: Return of ferocious storm, rising water and grim despair</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Emotional tension between adults facing death and children displaying courage</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch2-q3 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch2-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch2-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Describe the shifts in the narration of the events as indicated in the three sections of the text. Give a subtitle to each section.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The narrative undergoes distinct tonal and thematic shifts across three main sections:</p>\n      <ol style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>Section 1: The Joyous Voyage (Subtitle: <em>\"Smooth Sailing and Cheerful Ambition\"</em>)</strong>\n          <br>Covers the cheerful departure from Plymouth in July 1976 to round the world like Captain James Cook. The tone is buoyant, confident, and optimistic. The 105,000-kilometer leg to Cape Town passes smoothly, and they celebrate a joyous Christmas 3,500 km east of Cape Town despite rough seas.\n        </li>\n        <li><strong>Section 2: The Catastrophic Struggle (Subtitle: <em>\"Into the Jaws of the Tempest\"</em>)</strong>\n          <br>Begins on January 2 with gigantic waves and a deafening explosion that slams Wavewalker. The narrative turns breathless, intense, and visceral—detailing broken bones, punctured lungs, flooded cabins, failing pumps, and desperate repairs amidst freezing gale winds.\n        </li>\n        <li><strong>Section 3: The Triumph of Resilience (Subtitle: <em>\"Pinpricks in the Vast Ocean: Safe Haven\"</em>)</strong>\n          <br>Covers January 6 onward, characterized by precise navigation calculations, sheer mental determination, and overwhelming emotional relief when the captain spots the volcanic rock of Ile Amsterdam. The tone transforms into gratitude, celebrating human endurance and family unity.\n        </li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Section 1: Cheerful start with appropriate subtitle</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Section 2: Violent crisis and survival battle with subtitle</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Section 3: Mathematical rescue and island triumph with subtitle</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch2-q4 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch2-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch2-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        What difference did you notice between the reaction of the adults and the children when faced with danger?\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The story contrasts adult responsibility with childlike heroism when confronted by catastrophic danger:</p>\n      <ul style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>The Adults’ Reaction:</strong> The adults (the narrator, Mary, Larry Vigil, and Herb Seigler) reacted with pragmatic grit and intense dedication. They experienced terror and physical anguish, yet channeled it into relentless, disciplined action—steering, pumping, navigating, and repairing. When hope slipped away, they succumbed quietly to sorrow, holding hands in resigned acceptance of death.</li>\n        <li><strong>The Children’s Reaction:</strong> The children (seven-year-old Suzanne and six-year-old Jonathan) exhibited astonishing maturity, fearlessness, and emotional consideration:\n          <ul style=\"margin-left:20px; margin-top:4px;\">\n            <li><strong>Suzanne:</strong> Suffered a severely bumped forehead, black eyes, and a deep cut on her arm, yet concealed the full extent of her injuries so as not to distract her father while he fought to keep the ship afloat. Later, she presented a cheerful handmade card with caricatures of her parents to lift their spirits.</li>\n            <li><strong>Jonathan:</strong> Uttered the immortal words that gave the chapter its title: <em>\"We aren’t afraid of dying if we can all be together—you and Mummy, Sue and all of us.\"</em> This innocent display of unity renewed the father’s will to battle the ocean.</li>\n          </ul>\n        </li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Adult reaction: Practical action, disciplined pumping, psychological vulnerability</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Children reaction: Suzanne hiding head injury & Jonathan declaring fearlessness</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch2-q5 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch2-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch2-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        How does the story suggest that optimism helps to endure “the direst stress”?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The narrative is a testament to the transformative power of optimism when confronted by lethal circumstances:</p>\n      <ul style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>Unshakable Crew Morale:</strong> Despite icy seas pouring through shattered wood, Larry Vigil and Herb Seigler pumped cheerfully like madmen, refusing to surrender to despair.</li>\n        <li><strong>The Captain’s Mathematical Grit:</strong> Even with broken ribs, a damaged compass, and missing navigational equipment, the narrator continued calculating drift, leeway, and magnetic variation, pursuing a tiny 65-kilometer-wide island in 150,000 square kilometers of ocean.</li>\n        <li><strong>Emotional Anchor of Family:</strong> Suzanne’s humorous card and Jonathan’s inspiring fearlessness revitalized the father’s sinking spirits whenever exhaustion threatened to break his resolve.</li>\n        <li><strong>Conclusion:</strong> Optimism provided the voyagers with the mental fortitude to convert catastrophic panic into constructive action, ultimately steering them to safety at Ile Amsterdam.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Cheerfulness and sustained pumping by Larry and Herb under icy conditions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Father’s continuous navigation calculations despite severe injuries</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Children’s optimism acting as emotional fuel to overcome dire stress</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch2-q6 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch2-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch2-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        What lessons can be drawn from the voyagers’ experience for handling crisis and life-threatening situations?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The harrowing experience of Wavewalker offers timeless lessons in crisis management:</p>\n      <ol style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>Thorough Preparation:</strong> The family spent 16 years honing their seafaring skills and rigorously tested Wavewalker in the roughest British weather before undertaking the voyage. Preparedness is the first line of defense.</li>\n        <li><strong>Teamwork and Role Division:</strong> Everyone performed their assigned role without panic—Mary held the wheel, the crewmen operated pumps, and the captain sealed deck leaks.</li>\n        <li><strong>Mental Composure under Pressure:</strong> In life-or-death crises, panic accelerates disaster. Retaining calm composure allowed the captain to think rationally, find an auxiliary pump, and chart navigation coordinates.</li>\n        <li><strong>Mutual Empathy and Love:</strong> Caring for one another elevates human spirit above physical pain, generating superhuman endurance.</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Pre-voyage preparation and technical mastery of skills</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Seamless teamwork and calm rational thinking during disaster</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mutual empathy, emotional resilience and positive mental outlook</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(1)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 1</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(3)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 3 (Discovering Tut: the Saga Continues) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[3] = "<section class=\"chapter-section\" id=\"c11e-ch3\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">3</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Hornbill (Prose) &bull; Chapter 3</div>\n      <h2>Discovering Tut: the Saga Continues</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 6 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fef3c7, #fffbeb); border:1px solid #fde68a; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#78350f; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#d97706\" stroke-width=\"2\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"/><line x1=\"16\" y1=\"2\" x2=\"16\" y2=\"6\"/><line x1=\"8\" y1=\"2\" x2=\"8\" y2=\"6\"/><line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"/></svg>\n      Chronology of Modern Investigations on King Tut’s Mummy\n    </h3>\n    <svg viewBox=\"0 0 800 180\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <circle cx=\"120\" cy=\"90\" r=\"45\" fill=\"#fef3c7\" stroke=\"#d97706\" stroke-width=\"2\"/>\n      <text x=\"120\" y=\"85\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#78350f\">1922</text>\n      <text x=\"120\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" fill=\"#92400e\">Howard Carter</text>\n      <text x=\"120\" y=\"150\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">Discovery of Tomb</text>\n\n      <line x1=\"165\" y1=\"90\" x2=\"335\" y2=\"90\" stroke=\"#cbd5e1\" stroke-width=\"3\"/>\n\n      <circle cx=\"380\" cy=\"90\" r=\"45\" fill=\"#eff6ff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"380\" y=\"85\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#0369a1\">1968</text>\n      <text x=\"380\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" fill=\"#0284c7\">Anatomy Prof.</text>\n      <text x=\"380\" y=\"150\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">X-Ray: Missing Breastbone</text>\n\n      <line x1=\"425\" y1=\"90\" x2=\"595\" y2=\"90\" stroke=\"#cbd5e1\" stroke-width=\"3\"/>\n\n      <circle cx=\"640\" cy=\"90\" r=\"45\" fill=\"#ecfdf5\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"640\" y=\"85\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#065f46\">2005</text>\n      <text x=\"640\" y=\"105\" text-anchor=\"middle\" font-size=\"11\" fill=\"#059669\">Zahi Hawass</text>\n      <text x=\"640\" y=\"150\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">1,700 Multi-Slice CT Scan</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Understanding the Text & Talking About the Text</div>\n\n  <!-- c11e-ch3-q1 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch3-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch3-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Give reasons for the following: (i) King Tut’s body has been subjected to repeated scrutiny, (ii) Howard Carter’s investigation was resented, (iii) Carter had to chisel away the solidified resins to raise the king’s remains.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Detailed reasons for each of the archaeological milestones:</p>\n      <h4 style=\"color:#d97706; margin-top:8px;\">(i) King Tut’s body subjected to repeated scrutiny:</h4>\n      <p>King Tutankhamun was the last youthful heir of a magnificent royal dynasty that had ruled Egypt for centuries. He died unexpectedly as a teenager under mysterious circumstances. In addition to the immense gold treasures buried with him, historians and forensic experts were desperate to determine two unanswered questions: <em>How did he die?</em> and <em>How old was he at the time of his death?</em></p>\n      <h4 style=\"color:#d97706; margin-top:8px;\">(ii) Howard Carter’s investigation was resented:</h4>\n      <p>British archaeologist Howard Carter’s 1922 investigation was heavily resented because of his invasive, damaging methods. In his obsession to recover the solid gold coffin and priceless artifacts, Carter severed the mummy’s head and hacked off nearly every major joint to free the body from solidified ritual resins, permanently disfiguring Tut’s physical remains.</p>\n      <h4 style=\"color:#d97706; margin-top:8px;\">(iii) Carter chiseling away solidified resins:</h4>\n      <p>The ritual funerary resins used during Tut’s embalming had hardened over 3,300 years, cementing the mummy firmly to the bottom of the solid gold inner coffin. Carter initially attempted to soften the resins by setting the coffin outside in the blazing Egyptian sun at 149°F (65°C), but nothing budged. To prevent thieves from ripping the mummy apart for gold, Carter had no choice but to chisel the hardened resins away from beneath the limbs and torso.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Scrutiny due to royal dynasty end, mysterious teenage death & treasures</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Resentment due to destructive hacking and damage to the mummy</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Chiseling required because resins hardened like stone, unyielding to sun heat</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch3-q2 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch3-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch3-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Give reasons for the following: (i) Tut’s body was buried along with gilded treasures, (ii) The boy king changed his name from Tutankhaten to Tutankhamun.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Reasons grounded in ancient Egyptian theology and historical context:</p>\n      <h4 style=\"color:#d97706; margin-top:8px;\">(i) Why Tut’s body was buried with gilded treasures:</h4>\n      <p>The ancient Egyptian royals were unimaginably wealthy and firmly believed in the afterlife (resurrection). They believed the deceased king could take his riches into the next world. Therefore, Tut was buried with dazzling pure-gold artifacts—collars, inlaid neckpieces, bracelets, rings, amulets, sandals, and gold inner coffins—believed to guarantee immortality, alongside everyday necessities like board games, a bronze razor, linen garments, and cases of food and wine.</p>\n      <h4 style=\"color:#d97706; margin-top:8px;\">(ii) Why the boy king changed his name from Tutankhaten to Tutankhamun:</h4>\n      <p>Tut’s predecessor, the eccentric pharaoh Amenhotep IV (Akhenaten), had outlawed the worship of Egypt's major deity Amun, smashed his temples, closed his shrines, and promoted the sun disc god, Aten. When young Tut took power, he restored the ancient religion, reopened the temples of Amun, and changed his name from <em>Tutankhaten</em> (\"Living Image of Aten\") to <em>Tutankhamun</em> (\"Living Image of Amun\") to signal a religious restoration across Egypt.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Ancient belief in afterlife, resurrection & eternal guarantee of wealth</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Religious restoration of Amun worship after Akhenaten’s radical reign</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch3-q3 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch3-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch3-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        Scientific intervention is necessary to unearth buried mysteries. Discuss in groups/pairs.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Modern archaeology relies on non-invasive scientific technologies rather than destructive physical excavations:</p>\n      <ul style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>Non-Invasive Diagnostics:</strong> Traditional 19th-century archaeology focused on treasure-hunting and destructive physical extraction (e.g., Howard Carter). Modern scientific interventions—such as computed tomography (CT scanning), digital X-rays, carbon dating, and DNA fingerprinting—allow researchers to examine fragile antiquities without inflicting physical damage.</li>\n        <li><strong>High-Resolution Forensic Reconstruction:</strong> King Tut’s 2005 CT scan captured 1,700 digital cross-sectional X-ray images, reconstructing his skull, vertebrae, and ribs in microscopic millimeter slices, verifying that his breastbone and front ribs were indeed missing (likely from an ancient chest trauma).</li>\n        <li><strong>Conclusion:</strong> Science rescues historical truth from speculative mythology while preserving the cultural sanctity of ancient relics for posterity.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Contrast between destructive early archaeology and non-destructive modern tools</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">CT scans, digital X-rays, DNA analysis providing objective medical data</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Verification of historical anomalies while conserving ancient remains</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch3-q4 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch3-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch3-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        Advanced technology gives us conclusive evidence of past events. Discuss in groups/pairs.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>A balanced critical evaluation of advanced technological tools in historical inquiry:</p>\n      <ul style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>Points in Favor (High Precision Clues):</strong>\n          <br>Advanced tools provide incontrovertible anatomical and chronological data. In Tut’s case, the CT scan definitively disproved rumors that his head had been crushed by an execution weapon, verified his age at death as roughly 19 years, and confirmed that a broken leg had occurred shortly before death, possibly leading to a fatal infection.\n        </li>\n        <li><strong>Limitations (Need for Interpretive Context):</strong>\n          <br>While technology provides high-resolution anatomical cross-sections, it cannot reconstruct human intent, political conspiracies, or historical motives. For instance, whether Tut's chest injury occurred in battle, a chariot accident, or a court assassination remains open to historical deduction. Technology supplies the evidence; human historians must supply the contextual interpretation.\n        </li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Arguments supporting technological precision in physical and chronological facts</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Arguments highlighting boundaries where historical interpretation is still needed</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch3-q5 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch3-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch3-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        Traditions are paramount / Scientific research on ancient remains should be prohibited. What are the opposing viewpoints on this debate?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>An exploration of the ethical debate between cultural sanctity and scientific progress:</p>\n      <ul style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>In Favor of Preserving Traditions (Prohibiting Research on Remains):</strong>\n          <br>Every civilization has sacred funeral rituals designed to allow the dead to rest in eternal peace. Desecrating royal tombs, stripping shrouds, and transporting mummified human bodies through diagnostic scanners degrades sacred human remains into biological specimens. The fear of \"the pharaoh’s curse\" reflects humanity’s deep-seated ethical boundary against disturbing the repose of the deceased.\n        </li>\n        <li><strong>In Favor of Scientific Research (Unearthing Historical Truth):</strong>\n          <br>Historical inquiry is a vital human enterprise. Studying ancient remains sheds light on ancestral human genetics, prehistoric pathologies, medical practices, and societal collapses. Without scientific research, misconceptions and myths prevail over truth. Modern scans honor historical figures by documenting their lives accurately.\n        </li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Arguments for traditional respect and ethical inviolability of graves</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Arguments for scientific illumination, genetic history and medical archaeology</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch3-q6 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch3-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch3-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        What were the dramatic atmospheric and supernatural elements that accompanied King Tut’s CT scan in 2005?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The narrative highlights an eerie coincidence of nature and myth during the CT scan:</p>\n      <ul style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>Violent Desert Weather:</strong> An angry, dark wind whipped up desert sand into \"dark-bellied clouds\" tumbling across the Valley of the Kings, veiling the evening stars in a casket of grey haze.</li>\n        <li><strong>Machine Malfunction:</strong> When Tut’s body was placed inside the multimillion-dollar Siemens CT scanner, the cooling fan abruptly stopped working due to fine desert sand entering the mechanism. A nervous guard joked, <em>\"Curse of the pharaoh!\"</em></li>\n        <li><strong>Relief upon Completion:</strong> The diagnostic team successfully deployed two white substitute plastic fans to complete the scan. Once the data was secured and Tut was returned to his wooden coffin, the wind stopped completely, and a peaceful silence settled over the valley, with Orion—the ancient god of the afterlife—watching over the boy king.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Violent desert sandstorm and dark clouds over the Valley of the Kings</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Cooling fan failure caused by blowing desert sand and guard’s comment</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Resolution with backup fans and return of quiet peace under constellation Orion</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(2)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 2</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(4)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 4 (The Adventure) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[4] = "<section class=\"chapter-section\" id=\"c11e-ch4\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">4</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Hornbill (Prose) &bull; Chapter 4</div>\n      <h2>The Adventure</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 6 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fdf2f8, #f5f3ff); border:1px solid #e9d5ff; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#6b21a8; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#9333ea\" stroke-width=\"2\"><path d=\"M12 2v20\"/><path d=\"M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6\"/></svg>\n      The Physics of Alternate Reality: Catastrophe Theory & Quantum Parallel Worlds\n    </h3>\n    <svg viewBox=\"0 0 800 190\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"30\" y=\"30\" width=\"220\" height=\"130\" rx=\"8\" fill=\"#ffffff\" stroke=\"#9333ea\" stroke-width=\"2\"/>\n      <text x=\"140\" y=\"60\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#6b21a8\">Historical Reality A</text>\n      <text x=\"140\" y=\"85\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Real World (Known History)</text>\n      <text x=\"140\" y=\"110\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Vishwasrao shot in battle</text>\n      <text x=\"140\" y=\"128\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Marathas defeated at Panipat</text>\n      <text x=\"140\" y=\"146\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• British took over India</text>\n\n      <path d=\"M 250 95 L 340 95\" stroke=\"#94a3b8\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <circle cx=\"295\" cy=\"95\" r=\"14\" fill=\"#f3e8ff\" stroke=\"#9333ea\" stroke-width=\"2\"/>\n      <text x=\"295\" y=\"99\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"bold\" fill=\"#6b21a8\">VS</text>\n\n      <rect x=\"340\" y=\"30\" width=\"220\" height=\"130\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"450\" y=\"60\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#0369a1\">Transition Trigger</text>\n      <text x=\"450\" y=\"85\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Catastrophe Theory</text>\n      <text x=\"450\" y=\"110\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Gaitonde in truck collision</text>\n      <text x=\"450\" y=\"128\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Mind pondering Panipat</text>\n      <text x=\"450\" y=\"146\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Quantum state transition</text>\n\n      <path d=\"M 560 95 L 590 95\" stroke=\"#94a3b8\" stroke-width=\"3\"/>\n\n      <rect x=\"590\" y=\"30\" width=\"190\" height=\"130\" rx=\"8\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n      <text x=\"685\" y=\"60\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#15803d\">Alternate Reality B</text>\n      <text x=\"685\" y=\"85\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Parallel World Experienced</text>\n      <text x=\"685\" y=\"110\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Bullet missed Vishwasrao</text>\n      <text x=\"685\" y=\"128\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Marathas won Panipat</text>\n      <text x=\"685\" y=\"146\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Democratic Sovereign India</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Understanding the Text & Talking About the Text</div>\n\n  <!-- c11e-ch4-q1 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch4-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch4-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Tick whether each statement is True or False: (i) The story is an account of real events, (ii) The story hinges on a particular historical event, (iii) Rajendra Deshpande was a historian, (iv) The places mentioned in the story are all imaginary, (v) The story tries to relate history to science.\n      </div>\n      <div class=\"q-marks\">[5]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Evaluation of each statement based on the text:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li>(i) The story is an account of real events. &mdash; <strong style=\"color:#dc2626;\">[FALSE]</strong> (It is a science-fiction narrative exploring speculative alternate history and quantum theories).</li>\n        <li>(ii) The story hinges on a particular historical event. &mdash; <strong style=\"color:#16a34a;\">[TRUE]</strong> (It pivots on the outcome of the Third Battle of Panipat fought in 1761 between the Marathas and Ahmad Shah Abdali).</li>\n        <li>(iii) Rajendra Deshpande was a historian. &mdash; <strong style=\"color:#dc2626;\">[FALSE]</strong> (Rajendra Deshpande is an eminent physicist and mathematician; Professor Gangadharpant Gaitonde is the historian).</li>\n        <li>(iv) The places mentioned in the story are all imaginary. &mdash; <strong style=\"color:#dc2626;\">[FALSE]</strong> (Real geographical locations are featured, including Pune, Bombay/Mumbai, Victoria Terminus, Azad Maidan, and the Town Hall Asiatic Society Library).</li>\n        <li>(v) The story tries to relate history to science. &mdash; <strong style=\"color:#16a34a;\">[TRUE]</strong> (It correlates historical branch points with Catastrophe Theory and the Many-Worlds interpretation of Quantum Mechanics).</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) False identified with scientific fiction justification</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) True identified with Third Battle of Panipat</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) False identified with Deshpande as physicist</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iv) False identified with real geographical locations</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(v) True identified with Quantum & Catastrophe theories</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch4-q2 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch4-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch4-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Briefly explain the following statements from the text: (i) “You neither travelled to the past nor the future. You were in the present experiencing a different world.” (ii) “You have passed through a fantastic experience: or more correctly, a catastrophic experience.”\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Detailed explanations provided by Rajendra Deshpande to Professor Gaitonde:</p>\n      <h4 style=\"color:#6b21a8; margin-top:8px;\">(i) “You neither travelled to the past nor the future...”</h4>\n      <p>Rajendra clarifies that Gaitonde did not engage in physical time travel. He was not in the 18th century; he was in contemporary, modern-day Bombay, but in an <em>alternate parallel reality</em>. In quantum physics, multiple versions of reality can coexist simultaneously. Due to his subconscious fixation during a collision, Gaitonde made a quantum leap into another branch of reality existing right now in the present.</p>\n      <h4 style=\"color:#6b21a8; margin-top:8px;\">(ii) “You have passed through a fantastic experience: or more correctly, a catastrophic experience.”</h4>\n      <p>Rajendra uses the term \"catastrophic\" in a mathematical sense, invoking <strong>Catastrophe Theory</strong>. In non-linear systems, a tiny variation or tipping point can trigger a massive divergence of outcomes. In the Battle of Panipat, a bullet grazing Vishwasrao’s ear rather than killing him was a bifurcation point that completely reversed the outcome of the battle, altering the subsequent destiny of India.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of quantum parallel world existing in present time</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of Catastrophe Theory with historical bifurcation point</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch4-q3 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch4-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch4-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Briefly explain the following statements from the text: (i) Gangadharpant could not help comparing the country he knew with what he was witnessing around him, (ii) “The lack of determinism in quantum theory!” (iii) “You need some interaction to cause a transition.”\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Explanation of the theoretical and observational insights:</p>\n      <h4 style=\"color:#6b21a8; margin-top:8px;\">(i) Gangadharpant comparing the two Indias:</h4>\n      <p>In his known reality, India endured British colonization, partition, and administrative dependency. In the alternate Bombay he entered, India was a proud, self-reliant democratic nation where the East India Company operated only on leased commercial terms, the Marathas ruled from Delhi, and Indian technology and railways were modern and efficient.</p>\n      <h4 style=\"color:#6b21a8; margin-top:8px;\">(ii) “The lack of determinism in quantum theory!”:</h4>\n      <p>In classical physics, an object’s trajectory is deterministic and predictable. In quantum mechanics, an electron does not have a single fixed path; it can jump to different energy states unpredictably. Similarly, macroscopic reality is not deterministic—alternative outcomes do not disappear; they manifest in parallel quantum worlds.</p>\n      <h4 style=\"color:#6b21a8; margin-top:8px;\">(iii) “You need some interaction to cause a transition.”:</h4>\n      <p>Just as an electron requires an interaction (such as absorbing a photon) to transition between orbits, Gaitonde’s brain needed an external catalyst. The violent physical shock of the truck accident, synchronized with his intense mental pondering on \"what if the Marathas had won Panipat,\" triggered a neurological quantum transition into the parallel reality.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Comparison between colonized India and prosperous sovereign alternate India</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of quantum non-determinism and electron transitions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of accident + thoughts acting as catalytic transition</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch4-q4 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch4-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch4-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        A single event may change the course of the history of a nation. Discuss taking opposite points of view.\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Opposing philosophical and historical perspectives on historical turning points:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Arguments FOR (The \"Great Man\" / Tipping Point Theory):</strong>\n          <br>Proponents argue that pivotal moments often balance on knife-edge accidents. In the story, Vishwasrao surviving the gunshot preserved Maratha army morale, crushed Abdali’s troops, and blocked European colonial dominance. Real history exhibits similar critical events—the assassination of Archduke Franz Ferdinand sparking World War I, or the miraculous retreat at Dunkirk changing WWII.\n        </li>\n        <li><strong>Arguments AGAINST (Socioeconomic Determinism):</strong>\n          <br>Critics argue that history is driven by massive economic currents, technological advances, and demographic forces rather than isolated accidents. Even if Vishwasrao had survived, Maratha internal factionalism and European naval and industrial superiority might still have eventually altered India's balance of power. Isolated incidents may alter timelines, but underlying historical momentum dictates long-term destiny.\n        </li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Viewpoint FOR: Detailed tipping point examples and military morale impacts</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Viewpoint AGAINST: Socioeconomic determinism and macro-historical currents</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch4-q5 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch4-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch4-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        Reality is what is directly experienced through the senses. Discuss taking opposite points of view.\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>An exploration of sensory perception versus scientific and cognitive reality:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Arguments FOR (Empirical Realism):</strong>\n          <br>Human beings perceive existence through their senses—sight, sound, touch, smell, and taste. For Gaitonde, the alternate Bombay was undeniable: he held printed currency, ate in restaurants, read historical volumes in the Town Hall library, and was physically assaulted by an angry crowd at Azad Maidan. The torn page of the <em>Bhausahebanchi Bakhar</em> in his pocket was tangible, physical proof of his experience.\n        </li>\n        <li><strong>Arguments AGAINST (Quantum & Cognitive Science):</strong>\n          <br>Modern quantum physics demonstrates that reality is far vaster than human sensory apparatus. Phenomena like electromagnetic spectrums, quantum superposition, and subatomic particles cannot be perceived by naked senses yet are fundamentally real. Furthermore, human consciousness is vulnerable to hallucinations, coma states, and neural misfiring. Sensory experience is merely an interpretation generated by the brain, not absolute reality itself.\n        </li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Arguments FOR: Tangible sensory proof, physical receipt and library documents</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Arguments AGAINST: Limitations of human senses, quantum physics and neural states</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch4-q6 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch4-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch4-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        What tangible evidence convinced Rajendra Deshpande that Professor Gaitonde was not simply hallucinating?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Rajendra was initially skeptical, treating Gaitonde’s story as a traumatic concussion hallucination, until physical proof was presented:</p>\n      <ul style=\"margin-left:20px; margin-top:8px; line-height:1.7;\">\n        <li><strong>The Missing Page of the Bakhar:</strong> When Gaitonde reached into his pocket to retrieve his notes, he inadvertently pulled out a torn page from the <em>Bhausahebanchi Bakhar</em> that he had absentmindedly slipped into his pocket at the alternate Town Hall library.</li>\n        <li><strong>The Discrepancy in Text:</strong> Rajendra compared Gaitonde’s torn page with the accepted historical version of the <em>Bakhar</em>. In the real-world historical edition, the text read: <em>\"...and then Vishwasrao was guided to the battle and a bullet hit him; he fell dead.\"</em> But on Gaitonde’s page, the printed Marathi text declared: <em>\"...and then Vishwasrao was guided to the battle. A bullet brushed past his ear. By the grace of God, he was saved!\"</em></li>\n        <li><strong>Irrefutable Physical Reality:</strong> A hallucination cannot deposit a physically printed, ink-on-paper page from an alternate book inside a person's real jacket pocket. This physical anomaly proved Gaitonde had genuinely crossed quantum dimensional thresholds.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Torn page from the Bhausahebanchi Bakhar produced from pocket</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Textual proof: bullet grazing ear vs killing Vishwasrao</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Physical ink-and-paper evidence refuting pure psychological hallucination</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(3)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 3</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(5)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 5 (Silk Road) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[5] = "<section class=\"chapter-section\" id=\"c11e-ch5\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">5</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Hornbill (Prose) &bull; Chapter 5</div>\n      <h2>Silk Road</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 7 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #f0fdfa, #f5f3ff); border:1px solid #ccfbf1; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#0f766e; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#0d9488\" stroke-width=\"2\"><polygon points=\"3 11 22 2 13 21 11 13 3 11\"/></svg>\n      The Pilgrimage Route (Kora) Across the Tibetan Plateau\n    </h3>\n    <svg viewBox=\"0 0 800 170\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"20\" y=\"30\" width=\"160\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0d9488\" stroke-width=\"2\"/>\n      <text x=\"100\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#0f766e\">Ravu</text>\n      <text x=\"100\" y=\"75\" text-anchor=\"middle\" font-size=\"10\" fill=\"#475569\">Departure Point</text>\n      <text x=\"100\" y=\"95\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">• Farewell from Lhamo</text>\n      <text x=\"100\" y=\"112\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">• Gift: Sheepskin coat</text>\n\n      <path d=\"M 180 85 L 210 85\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"210\" y=\"30\" width=\"160\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"290\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#0369a1\">High Passes</text>\n      <text x=\"290\" y=\"75\" text-anchor=\"middle\" font-size=\"10\" fill=\"#475569\">5,515m Altitude</text>\n      <text x=\"290\" y=\"95\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">• Kyang & Tibetan mastiffs</text>\n      <text x=\"290\" y=\"112\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">• Treacherous snow turns</text>\n\n      <path d=\"M 370 85 L 400 85\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"400\" y=\"30\" width=\"160\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"480\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#dc2626\">Hor & Darchen</text>\n      <text x=\"480\" y=\"75\" text-anchor=\"middle\" font-size=\"10\" fill=\"#475569\">Grim Reality</text>\n      <text x=\"480\" y=\"95\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">• Desolate, dusty Hor</text>\n      <text x=\"480\" y=\"112\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">• Chest congestion at Darchen</text>\n\n      <path d=\"M 560 85 L 590 85\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"590\" y=\"30\" width=\"190\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#16a34a\" stroke-width=\"2\"/>\n      <text x=\"685\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#15803d\">Mount Kailash</text>\n      <text x=\"685\" y=\"75\" text-anchor=\"middle\" font-size=\"10\" fill=\"#475569\">Sacred Kora with Norbu</text>\n      <text x=\"685\" y=\"95\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">• Meets Tibetan scholar Norbu</text>\n      <text x=\"685\" y=\"112\" text-anchor=\"middle\" font-size=\"9\" fill=\"#64748b\">• Hires yaks for pilgrimage</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Understanding the Text & Talking About the Text</div>\n\n  <!-- c11e-ch5-q1 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch5-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch5-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Give reasons for the following: (i) The article has been titled ‘Silk Road’, (ii) Tibetan mastiffs were popular in China’s imperial courts, (iii) The author’s experience at Hor was in stark contrast to earlier accounts of the place.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Detailed reasons grounded in geography, cultural history, and travel literature:</p>\n      <h4 style=\"color:#0f766e; margin-top:8px;\">(i) Why the article is titled ‘Silk Road’:</h4>\n      <p>The journey retraces parts of the ancient Silk Road—the historic trading network connecting China, Central Asia, India, and the Mediterranean. The author, a physical geographer, traveled along these ancient high-altitude trade corridors across the Tibetan plateau towards Mount Kailash to undertake the sacred Buddhist pilgrimage (<em>Kora</em>).</p>\n      <h4 style=\"color:#0f766e; margin-top:8px;\">(ii) Why Tibetan mastiffs were popular in China’s imperial courts:</h4>\n      <p>Tibetan mastiffs were enormous, ferocious black guard dogs with massive heads, explosive barks, and absolute fearlessness. They were trained by Tibetan nomads (<em>drokbas</em>) to guard encampments and fiercely chase away any intruder. Because of their fierce loyalty and hunting prowess, they were brought along the Silk Road as royal tributes to Chinese emperors to serve as guard dogs.</p>\n      <h4 style=\"color:#0f766e; margin-top:8px;\">(iii) Author’s experience at Hor in contrast to earlier accounts:</h4>\n      <p>Earlier accounts by travelers like Japanese monk Ekai Kawaguchi (who wept at the sublime purity of Lake Manasarovar) and Swedish explorer Sven Hedin depicted Hor as a place of spiritual transcendence. In stark contrast, Nick Middleton found Hor to be a desolate, wretched, and grim settlement strewn with dust, rocks, and decades of rusted tin cans and garbage, devoid of any natural vegetation.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Traversal of historic trade routes towards Mount Kailash kora</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Enormous ferocity, loyalty and tribute status in imperial courts</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Disillusionment: dirty, barren, trash-strewn settlement vs spiritual accounts</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch5-q2 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch5-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch5-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Give reasons for the following: (i) The author was disappointed with Darchen, (ii) The author thought that his positive thinking strategy worked well after all.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Detailed psychological and situational analysis:</p>\n      <h4 style=\"color:#0f766e; margin-top:8px;\">(i) The author was disappointed with Darchen:</h4>\n      <p>The author reached Darchen dusty and physically exhausted, only to fall acutely ill with severe sinus blockage and nocturnal breathing difficulties at the high altitude. Furthermore, Darchen was drab, dusty, and full of garbage heaps. To his immense dismay, he had arrived early in the season—there were no other pilgrims, the town had a derelict feel, and he found nobody who could speak English to help him organize his <em>Kora</em>.</p>\n      <h4 style=\"color:#0f766e; margin-top:8px;\">(ii) The author thought his positive thinking strategy worked well:</h4>\n      <p>Feeling stranded, lonely, and medically drained in Darchen's solitary cafe, Middleton resolved to maintain a positive mental outlook. Almost immediately, he encountered Norbu, a jovial Tibetan scholar working at the Chinese Academy of Social Sciences in Beijing. Norbu spoke fluent English, was also carrying an English academic book, and was visiting to perform the <em>Kora</em> himself. The two struck an instant friendship and decided to team up, hiring yaks to carry their luggage, proving to the author that optimism had yielded an ideal outcome.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Acute altitude sickness, lack of pilgrims, and language barrier at Darchen</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Serendipitous meeting with English-speaking academic partner Norbu</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch5-q3 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch5-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch5-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Briefly comment on: (i) The purpose of the author’s journey to Mount Kailash, (ii) The author’s physical condition in Darchen, (iii) The author’s meeting with Norbu.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Commentary on central narrative facets:</p>\n      <h4 style=\"color:#0f766e; margin-top:8px;\">(i) Purpose of author’s journey to Mount Kailash:</h4>\n      <p>As an academic geographer, Nick Middleton wished to experience the extreme geography of Tibet and complete the traditional <em>Kora</em> (circumambulation) around sacred Mount Kailash. While motivated partly by cultural appreciation, his drive was primarily that of an intrepid travel writer and geographer exploring remote terrains.</p>\n      <h4 style=\"color:#0f766e; margin-top:8px;\">(ii) Physical condition in Darchen:</h4>\n      <p>At an altitude of over 4,500 meters, Middleton suffered from acute mountain sickness. His nasal passages were congested, his chest felt heavy, and whenever he lay flat on his mattress, his breath choked, causing heart palpitations. He spent a sleepless night sitting upright in terror before Tsetan took him to the local Tibetan medical college, where a five-day herbal concoction restored his health.</p>\n      <h4 style=\"color:#0f766e; margin-top:8px;\">(iii) Meeting with Norbu:</h4>\n      <p>Sitting alone in Darchen’s rustic cafe, Middleton met Norbu, who noticed the author reading an English novel. Norbu turned out to be an unconventional pilgrim—an urban Tibetan academic who wrote papers on the Kailash <em>Kora</em> but had never actually undertaken it. Both were slightly out of shape and had no desire to prostrate themselves around the mountain, making them well-matched trekking companions.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Geographer’s desire to experience the sacred Kailash kora</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Altitude-induced sleep apnea, sinus blockage and Tibetan herbal cure</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) Pragmatic partnership with Tibetan academic researcher Norbu</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch5-q4 (Understanding the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch5-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch5-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Understanding the Text</span><br>\n        Briefly comment on: (i) Tsetan’s support to the author during the journey, (ii) “As a Buddhist, he told me, he knew that it didn’t really matter if I passed away, but he thought it would be bad for business.”\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Analysis of character dynamics and cultural worldview:</p>\n      <h4 style=\"color:#0f766e; margin-top:8px;\">(i) Tsetan’s support during the journey:</h4>\n      <p>Tsetan was an exceptional driver, mechanic, and companion. He skillfully maneuvered his four-wheel-drive vehicle across treacherous iced tracks and high passes (5,515 m), throwing dirt on snow to gain traction. When the author fell sick in Darchen, Tsetan took him directly to the medical college, translated his symptoms to the Tibetan doctor, and ensured he was on the road to recovery before departing.</p>\n      <h4 style=\"color:#0f766e; margin-top:8px;\">(ii) Meaning of Tsetan’s Buddhist remark:</h4>\n      <p>This humorous yet profound statement reflects a pragmatic collision of Buddhist philosophy and commercial livelihood. As a practicing Tibetan Buddhist, Tsetan viewed bodily death as merely a transition of the soul to its next incarnation, hence \"it didn't really matter.\" However, as a professional travel guide and driver, having a Western tourist die under his care in Darchen would be devastating for his tourism business reputation.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Exceptional mountain driving, icy road maneuvering and healthcare support</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Blend of Buddhist spiritual detachment regarding death and commercial realism</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch5-q5 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch5-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch5-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        Discuss the sensitive and generous behaviour of hill-folk as observed in the chapter.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The author’s travelogue highlights the warm, hospitable nature of high-altitude Himalayan communities:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Lhamo’s Parting Gift:</strong> Before the author left Ravu, Lhamo gave him a traditional long-sleeved sheepskin coat (<em>chuba</em>), recognizing that he would freeze in the biting winds of the high passes. She demonstrated genuine, thoughtful maternal concern for a departing guest.</li>\n        <li><strong>Tsetan’s Unfailing Loyalty:</strong> Tsetan cared for the author beyond commercial duty. When Middleton struggled to breathe, Tsetan personally escorted him to the medical college in the middle of the night and waited until he showed improvement.</li>\n        <li><strong>Innocence Uncorrupted by Commercialism:</strong> Despite living in harsh, impoverished environments, the hill folk maintain simplicity, spiritual calm, and genuine human warmth.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Lhamo’s gift of the sheepskin coat showing thoughtful hospitality</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Tsetan’s patient guidance, driving skill and medical care</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">General ethos of simplicity and community solidarity among hill people</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch5-q6 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch5-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch5-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        What precautions should travelers take when visiting high-altitude regions like Tibet or Ladakh?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Essential health and logistical guidelines for high-altitude expeditions:</p>\n      <ol style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Gradual Acclimatization:</strong> Ascend slowly to allow the body to adapt to lower oxygen levels and barometric pressure, preventing Acute Mountain Sickness (AMS) or High Altitude Pulmonary Edema (HAPE).</li>\n        <li><strong>Medical Preparedness:</strong> Carry altitude sickness medication (e.g., Diamox), nasal decongestants, portable oxygen cans, and essential pain relievers.</li>\n        <li><strong>Adequate Hydration & Nutrition:</strong> Drink copious amounts of water and warm fluids to counter extreme atmospheric dryness, and consume calorie-rich, easily digestible food.</li>\n        <li><strong>Layered Thermal Clothing:</strong> Wear windproof and waterproof insulated gear, thermal inners, UV-protective sunglasses, and heavy fleece gloves to guard against severe hypothermia and frostbite.</li>\n        <li><strong>Experienced Local Guides:</strong> Travel with licensed local drivers familiar with unpredictable mountain blizzards, black ice, and river crossings.</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Gradual acclimatization and pacing of altitude gain</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Medical kit (Diamox, oxygen, decongestants) and hydration</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Thermal clothing layers and relying on experienced local drivers</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch5-q7 (Talking About the Text) -->\n  <div class=\"q-card\" id=\"c11e-ch5-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch5-q7')\">\n      <div class=\"q-num\">Question 7</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Talking About the Text</span><br>\n        Describe the author’s encounter with the Tibetan medical practitioner and the treatment prescribed.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The author’s encounter with Tibetan traditional medicine in Darchen was surprisingly effective:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>The Setting:</strong> The Tibetan Medical College in Darchen was rustic, resembling a monastery courtyard with plain stone buildings and no white coats or diagnostic machines.</li>\n        <li><strong>The Diagnosis:</strong> The doctor wore traditional Tibetan garb. Instead of a stethoscope, he carefully felt the author’s pulse at the wrists, observing his eyes and tongue. He diagnosed the condition as a severe cold compounded by the effects of extreme altitude.</li>\n        <li><strong>The Treatment:</strong> The doctor provided a five-day supply of Tibetan herbal remedies packed in fifteen small brown paper packets. The morning dose was a brown powder taken with hot water (tasting like cinnamon), and the lunch and bedtime doses were small brown pellets. The remedies proved miraculously effective—Middleton slept soundly that very night.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Rustic clinic setting without modern diagnostic machinery</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pulse diagnosis by Tibetan physician identifying cold & altitude shock</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Fifteen brown herbal powder packets providing immediate, restful relief</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(4)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 4</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(6)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 6 (A Photograph) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[6] = "<section class=\"chapter-section\" id=\"c11e-ch6\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">6</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Hornbill (Poetry) &bull; Chapter 6</div>\n      <h2>A Photograph</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 6 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #f8fafc, #ede9fe); border:1px solid #ddd6fe; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#5b21b6; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"2\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><circle cx=\"8.5\" cy=\"8.5\" r=\"1.5\"/><polyline points=\"21 15 16 10 5 21\"/></svg>\n      Thematic Structure: Three Stages of Time & Mourning\n    </h3>\n    <svg viewBox=\"0 0 800 160\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#7c3aed\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#5b21b6\">Past: Childhood</text>\n      <text x=\"137\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">The Beach Holiday</text>\n      <text x=\"137\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Mother aged 12 with cousins</text>\n      <text x=\"137\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Carefree sea paddling</text>\n\n      <path d=\"M 250 80 L 285 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#0369a1\">Middle: 20-30 Years Later</text>\n      <text x=\"397\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">The Mother’s Laughter</text>\n      <text x=\"397\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Mother laughs at snapshot</text>\n      <text x=\"397\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Nostalgia for lost youth</text>\n\n      <path d=\"M 510 80 L 545 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"25\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#dc2626\">Present: Bereavement</text>\n      <text x=\"660\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">The Daughter’s Silence</text>\n      <text x=\"660\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Mother dead 12 years</text>\n      <text x=\"660\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"Its silence silences\"</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Think It Out & Poetic Appreciation</div>\n\n  <!-- c11e-ch6-q1 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch6-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch6-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        What does the word ‘cardboard’ denote in the poem? Why has this word been used?\n      </div>\n      <div class=\"q-marks\">[2]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The word <strong>‘cardboard’</strong> denotes the stiff, thick backing on which the vintage black-and-white photograph of the poet’s mother and her cousins is mounted.</p>\n      <p>The poet specifically uses the word ‘cardboard’ for multiple literary reasons:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Frail and Insubstantial Medium:</strong> Unlike marble or enduring stone monuments, cardboard is a cheap, perishable material that inevitably yellows and degrades over time, underscoring the fragility of human records.</li>\n        <li><strong>Stark Contrast between Inanimate Matter & Mortal Life:</strong> The lifeless, stiff piece of cardboard has survived for decades, outlasting the vibrant, living human being it portrays. It ironically emphasizes the transience of human life compared to ordinary, inanimate objects.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Cardboard refers to the stiff photograph mounting board</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Signifies perishability and ironic durability over human mortality</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch6-q2 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch6-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch6-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        What has the camera captured?\n      </div>\n      <div class=\"q-marks\">[2]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The camera captured an innocent, sunlit beach holiday from the distant past:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>The Subjects:</strong> The poet's mother when she was about twelve years old, flanked by her two younger cousins, Betty and Dolly. Each cousin was holding one of her hands as they were paddling in the coastal shallows.</li>\n        <li><strong>The Moment:</strong> The three girls stood smiling with their sea-blown hair framing their faces, looking directly into the camera held by their uncle.</li>\n        <li><strong>The Contrast:</strong> It captures a youthful, carefree moment of laughter frozen in time before adulthood, motherhood, and mortality overtook them.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Mother at age 12 paddling in the sea with cousins Betty and Dolly</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Smiling faces through windblown hair photographed by the uncle</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch6-q3 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch6-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch6-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        What has not changed over the years? Does this suggest something to you?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The <strong>sea</strong> has not changed over the years. Its restless waves wash the shore today in precisely the same manner as they did when the three young girls stood there decades ago.</p>\n      <p><strong>Philosophical Suggestion:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Permanence vs. Transience:</strong> This creates a poignant contrast between the immortal, unchanging permanence of Nature and the fleeting, perishable nature of human life.</li>\n        <li><strong>The Transferred Epithet:</strong> The poet underscores this through the memorable poetic phrase <em>“terribly transient feet.”</em> While the mortal human feet undergo growth, aging, decay, and death, the sea remains immortal and unblemished by the passage of time.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of the sea as the unchanging element over time</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Contrast between immortal Nature and mortal human transience</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of \"terribly transient feet\" (transferred epithet)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch6-q4 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch6-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch6-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        The poet’s mother laughed at the snapshot. What did this laugh indicate?\n      </div>\n      <div class=\"q-marks\">[2]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The mother’s laugh, occurring some twenty to thirty years after the beach holiday, indicates a complex mixture of nostalgia, amusement, and bittersweet acceptance:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Amusement at Childhood Dress:</strong> She was amused by the old-fashioned beach clothes that Betty, Dolly, and she were made to wear by their parents for the seaside holiday.</li>\n        <li><strong>Nostalgia for Lost Innocence:</strong> The laughter expressed fondness for a carefree, innocent childhood that was gone forever. It demonstrated her ability to look back on lost youth with grace and cheerful resignation.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Amusement at old-fashioned seaside attire chosen by parents</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Nostalgia for innocence and bittersweet acceptance of lost childhood</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch6-q5 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch6-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch6-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        What is the meaning of the line “Both wry with the laboured ease of loss”?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>This profound line encapsulates the central emotional core of the poem through an <strong>oxymoron</strong> (<em>“laboured ease”</em>):</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Two Different Losses:</strong>\n          <br><strong>The Mother’s Loss:</strong> The sea holiday of her youth was the mother's past, which she mourned with a nostalgic smile.\n          <br><strong>The Poet’s Loss:</strong> Her deceased mother’s laughter is the poet's past, which the poet now mourns in grief.\n        </li>\n        <li><strong>The Paradox of ‘Laboured Ease’:</strong> Both the mother and daughter have had to struggle intensely (<em>“laboured”</em>) over years to come to terms with their respective irrevocable losses, until time forces an outward calm or acceptance (<em>“ease”</em>). Yet, the lingering pain leaves a twisted, bittersweet, or ironic expression (<em>“wry”</em>) on the face.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of the two parallel losses (mother’s childhood & poet’s mother)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of the oxymoron \"laboured ease\" (struggle yielding forced acceptance)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Significance of \"wry\" as bittersweet, ironic sorrow</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch6-q6 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch6-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch6-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        What does “this circumstance” refer to? Explain: “Its silence silences.”\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>“This circumstance”</strong> refers to the present state of bereavement—the permanent absence and death of the poet’s mother, who has now been dead nearly as many years as the twelve-year-old girl in the photograph had lived.</p>\n      <p><strong>Explanation of “Its silence silences”:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Alliteration & Personification:</strong> The repetition of the soft 's' sound mimics the quiet, heavy vacuum of grief.</li>\n        <li><strong>Absolute Speechlessness:</strong> The circumstance of death is so final and absolute that there are no words left to express or console the profound ache of loss. The silence of the dead mother and the grave envelopes the living daughter, rendering her completely speechless. Death’s final silence silences all human expression.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">\"This circumstance\" defined as the mother’s death and permanent absence</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Alliteration and sonic imagery of \"silence silences\"</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Total paralysis of speech in the face of profound, terminal grief</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(5)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 5</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(7)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 7 (The Laburnum Top) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[7] = "<section class=\"chapter-section\" id=\"c11e-ch7\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">7</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Hornbill (Poetry) &bull; Chapter 7</div>\n      <h2>The Laburnum Top</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 5 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fefce8, #fef08a); border:1px solid #fde047; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#854d0e; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#ca8a04\" stroke-width=\"2\"><path d=\"M12 2a10 10 0 1 0 10 10A10 10 0 0 0 12 2zm1 14.93V17a1 1 0 0 1-2 0v-.07A7 7 0 0 1 5.07 11H5a1 1 0 0 1 0-2h.07A7 7 0 0 1 11 3.07V3a1 1 0 0 1 2 0v.07A7 7 0 0 1 18.93 9H19a1 1 0 0 1 0 2h-.07A7 7 0 0 1 13 16.93z\"/></svg>\n      The Dynamic Cycle of Life in \"The Laburnum Top\"\n    </h3>\n    <svg viewBox=\"0 0 800 160\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <circle cx=\"130\" cy=\"80\" r=\"50\" fill=\"#ffffff\" stroke=\"#ca8a04\" stroke-width=\"2\"/>\n      <text x=\"130\" y=\"75\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#854d0e\">Stillness</text>\n      <text x=\"130\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">Silent, Yellow, Empty</text>\n\n      <path d=\"M 185 80 L 295 80\" stroke=\"#94a3b8\" stroke-width=\"3\" marker-end=\"url(#arrow)\"/>\n\n      <circle cx=\"400\" cy=\"80\" r=\"55\" fill=\"#fef08a\" stroke=\"#ca8a04\" stroke-width=\"2.5\"/>\n      <text x=\"400\" y=\"70\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#713f12\">Goldfinch Arrives</text>\n      <text x=\"400\" y=\"90\" text-anchor=\"middle\" font-size=\"11\" fill=\"#854d0e\">Engine of Her Family</text>\n      <text x=\"400\" y=\"108\" text-anchor=\"middle\" font-size=\"9\" fill=\"#a16207\">Chitterings & Tremor of Wings</text>\n\n      <path d=\"M 510 80 L 615 80\" stroke=\"#94a3b8\" stroke-width=\"3\"/>\n\n      <circle cx=\"670\" cy=\"80\" r=\"50\" fill=\"#ffffff\" stroke=\"#ca8a04\" stroke-width=\"2\"/>\n      <text x=\"670\" y=\"75\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#854d0e\">Subsides Empty</text>\n      <text x=\"670\" y=\"95\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">Infinite Silence Returns</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Find Out & Think It Out</div>\n\n  <!-- c11e-ch7-q1 (Find Out) -->\n  <div class=\"q-card\" id=\"c11e-ch7-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch7-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Find Out</span><br>\n        What is the Laburnum tree called in your language? Which local bird is like the goldfinch?\n      </div>\n      <div class=\"q-marks\">[2]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Language Equivalent:</strong></p>\n      <p>In Hindi and most Indian vernacular languages, the Laburnum tree is called the <strong>‘Amaltaas’ (अमलतास)</strong> tree. It is characterized by drooping yellow flower clusters, medicinal pods, and poisonous seeds.</p>\n      <p><strong>Similar Local Bird:</strong></p>\n      <p>The local bird closely resembling the goldfinch in plumage and size is the <strong>Indian Lutino Ringneck</strong> or the <strong>Yellow-throated Bulbul / Greenfinch (or Eurasian Siskin)</strong>, which exhibits vibrant yellow-streaked plumage, brisk flight, and melodious whistling calls.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Laburnum identified as Amaltaas in Hindi</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Bird identified as Yellow Bulbul / Indian Lutino Ringneck / Siskin</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch7-q2 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch7-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch7-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        What do you notice about the beginning and the ending of the poem?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Ted Hughes crafts a striking <strong>circular structure</strong> connecting the poem’s opening and conclusion:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>The Beginning:</strong> The poem opens with quiet desolation: <em>“The Laburnum top is silent, quite still”</em> in the yellow September afternoon sunlight, with yellowing leaves and fallen seeds. It resembles a lifeless corpse.</li>\n        <li><strong>The Ending:</strong> After the goldfinch launches away into the infinite blue sky, the poem concludes with the exact same quietude: <em>“and the laburnum subsides to empty.”</em></li>\n        <li><strong>Significance:</strong> The bird’s energetic arrival is a transient burst of maternal energy that temporarily awakens the inanimate tree into an engine of life before returning it to primeval silence.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Beginning describes motionless, silent, death-like laburnum top</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ending returns to primeval emptiness once goldfinch flies away</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Significance of circular structure emphasizing transience of vital energy</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch7-q3 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch7-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch7-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        To what is the bird’s movement compared? What is the basis for the comparison?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The bird’s entry into the thick foliage is compared to the movement of a <strong>lizard</strong> (<em>“Sleek as a lizard, and alert, and abrupt”</em>).</p>\n      <p><strong>Basis for Comparison:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Sleek & Smooth:</strong> Like a lizard gliding silently over a surface without creating a rustle, the goldfinch slips into the dense yellow foliage with effortless grace.</li>\n        <li><strong>Alert & Cautious:</strong> Both creatures display hyper-vigilance, looking around sharply to ensure predators are not observing their movements.</li>\n        <li><strong>Abrupt & Rapid:</strong> A lizard makes sudden, darting stops and quick dashes; similarly, the bird makes sudden, sharp movements before vanishing into the interior of the tree to feed her young.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Movement compared to a lizard using simile</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Smooth, sleek gliding entry into thick branches</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Alert vigilance and abrupt, quick darting movements shared by both</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch7-q4 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch7-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch7-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        Why is the image of the engine evoked by the poet?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The poet invokes the industrial metaphor of an <strong>engine</strong> because of how energy and movement are generated within the quiet tree:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Source of Energy & Power:</strong> Just as an engine is the beating heart that sets a lifeless machine or locomotive into roaring motion, the goldfinch is the vital source that sets her hidden brood into frenzied activity.</li>\n        <li><strong>Sonic Symphony:</strong> When the mother bird enters with food, the nestlings erupt into a mechanical chorus of <em>“chitterings, and a tremor of wings, and trillings.”</em> The entire tree vibrates and shivers like a roaring motor.</li>\n        <li><strong>Fueling the Engine:</strong> Hughes writes: <em>“She stokes that engine full.”</em> The mother bird feeds her offspring with nutrient-rich food (stoking fuel) before flitting out to a branch end.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Metaphor of engine as the source of kinetic power for a machine</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Nestlings’ eruption of chitterings and wing-tremors compared to machine noise</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Maternal feeding described as \"stoking the engine\" with fuel</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch7-q5 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch7-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch7-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        What does the phrase “her barred face identity mask” mean?\n      </div>\n      <div class=\"q-marks\">[2]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The phrase refers to the unique facial markings of the goldfinch and their symbolic role in nature:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Camouflage & Disguise:</strong> The goldfinch’s body has yellowish plumage that blends seamlessly into the yellowing leaves and yellow blossoms of the Laburnum tree, rendering her invisible to the external world.</li>\n        <li><strong>The Barred Identification:</strong> Her face carries distinctive dark bars or black markings across the eyes. While the rest of her body remains camouflaged, this striped, barred face acts as her \"identity badge\" or \"mask\" by which her hungry chicks instantly recognize their mother amidst the dense foliage.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Yellow plumage camouflaging her body within yellow laburnum leaves</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Dark striped facial bars acting as an identifying recognition badge for chicks</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(6)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 6</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(8)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 8 (The Voice of the Rain) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[8] = "<section class=\"chapter-section\" id=\"c11e-ch8\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">8</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Hornbill (Poetry) &bull; Chapter 8</div>\n      <h2>The Voice of the Rain</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 6 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #eff6ff, #dbeafe); border:1px solid #bfdbfe; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#1e40af; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2\"><path d=\"M17.5 19H9a7 7 0 1 1 6.71-9h1.79a4.5 4.5 0 1 1 0 9Z\"/></svg>\n      The Eternal Cycle: Parallel Between Rain & Song\n    </h3>\n    <svg viewBox=\"0 0 800 160\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"30\" y=\"25\" width=\"220\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n      <text x=\"140\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e40af\">Birth / Origin</text>\n      <text x=\"140\" y=\"80\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Earth & Water Body</text>\n      <text x=\"140\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">Rises impalpable (Vapor)</text>\n      <text x=\"140\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">Issuing from poet's heart</text>\n\n      <path d=\"M 255 80 L 290 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"290\" y=\"25\" width=\"220\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"400\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#0369a1\">Transformation & Wandering</text>\n      <text x=\"400\" y=\"80\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Vaguely Formed Clouds</text>\n      <text x=\"400\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">Altogether changed, yet same</text>\n      <text x=\"400\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">Song travels to all listeners</text>\n\n      <path d=\"M 515 80 L 550 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"550\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"662\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">Descent & Return with Love</text>\n      <text x=\"662\" y=\"80\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Nourishment & Fulfillment</text>\n      <text x=\"662\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">Revives dormant unborn seeds</text>\n      <text x=\"662\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">Duly with love returns</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Think It Out & Scientific Parallels</div>\n\n  <!-- c11e-ch8-q1 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch8-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch8-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        There are two voices in the poem. Who do they belong to? Which lines indicate this?\n      </div>\n      <div class=\"q-marks\">[2]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The poem is structured as an imaginary, philosophical dialogue between two distinct voices:</p>\n      <ol style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>The Voice of the Poet:</strong>\n          <br>Indicated in the opening line: <em>“And who art thou? said I to the soft-falling shower,”</em>\n        </li>\n        <li><strong>The Voice of the Rain:</strong>\n          <br>Indicated in lines 3 and 4: <em>“I am the Poem of Earth, said the voice of the rain,”</em>\n        </li>\n      </ol>\n      <p>Whitman uses <strong>personification</strong> to give the shower of rain a vocal consciousness capable of translating its ecological mission into human language.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of the poet and rain voices with exact textual quotes</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of personification giving conscious speech to rain</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch8-q2 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch8-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch8-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        What does the phrase “strange to tell” mean?\n      </div>\n      <div class=\"q-marks\">[2]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The phrase <strong>“strange to tell”</strong> conveys the poet’s sheer wonder, amazement, and disbelief.</p>\n      <p>When the poet casually addresses the falling shower with the inquiry <em>\"Who art thou?\"</em>, he never expected an answer from an inanimate meteorological phenomenon. To his pleasant astonishment, the rain responded in an articulate, poetic voice that the poet felt compelled to transcribe and translate into human language.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Poet’s surprise and wonder at an unexpected reply from nature</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Rain responding with articulate voice requiring translation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch8-q3 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch8-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch8-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        There is a parallel drawn between rain and music. Which words indicate this? Explain the similarity between the two.\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The parallel between rain and music is explicitly established when rain proclaims herself to be the <strong>“Poem of Earth”</strong>, and elaborated in the final bracketed lines:</p>\n      <blockquote style=\"margin:8px 0; padding:8px 16px; background:#f1f5f9; border-left:4px solid #2563eb; font-style:italic;\">\n        “(For song, issuing from its birth-place, after fulfilment, wandering / Reck’d or unreck’d, duly with love returns.)”\n      </blockquote>\n      <p><strong>Similarities between Rain and Song (Music):</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Origin:</strong> A song originates from the soul or heart of a poet/singer; rain originates from the land and bottomless ocean depths.</li>\n        <li><strong>Wandering & Transformation:</strong> A song travels across the world, touching diverse listeners; rain rises into the skies as invisible vapor, condensates into clouds, and wanders through atmospheric heavens.</li>\n        <li><strong>Disregard for Recognition:</strong> Whether heard and appreciated (<em>“reck’d”</em>) or ignored (<em>“unreck’d”</em>), neither ceases its mission.</li>\n        <li><strong>Return with Love:</strong> Both return with love to replenish their birthplace—song returns to the singer's heart as joy and artistic fulfillment, while rain returns to the parched earth to revive seeds and wash away dust layers.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Textual quote indicating parallel (Poem of Earth / bracketed song lines)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Shared origins (poet’s soul vs earth and water bodies)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Wandering whether reck’d or unreck’d</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final return with love to purify and beautify their birthplace</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch8-q4 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch8-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch8-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        How is the cyclic movement of rain brought out in the poem? Compare it with what you have learnt in science.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Walt Whitman poeticizes the scientific <strong>hydrological (water) cycle</strong> through evocative verses:</p>\n      <ol style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Evaporation (Ascent):</strong> The poem states that rain rises <em>“impalpable out of the land and the bottomless sea”</em> into the heavens. In science, water evaporates invisibly from water bodies as vapor due to solar heating.</li>\n        <li><strong>Condensation (Formation):</strong> In the heavens, it is <em>“vaguely form’d, altogether changed, and yet the same.”</em> Scientifically, invisible vapor cools and condenses around microscopic dust particles to form clouds; its physical state changes from gas to droplets, yet its chemical nature ($H_2O$) remains identical.</li>\n        <li><strong>Precipitation (Descent):</strong> Rain descends to <em>“lave the droughts, atomies, dust-layers of the globe”</em> and germinate <em>“seeds that had been only latent, unborn.”</em> Scientifically, precipitation brings moisture back to earth, recharging aquifers and stimulating plant germination.</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Ascent: Impalpable rising mapped to scientific evaporation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Condensation: \"Vaguely form’d, altogether changed yet same\" mapped to cloud formation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Descent: Laving droughts and germinating seeds mapped to precipitation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch8-q5 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch8-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch8-q5')\">\n      <div class=\"q-num\">Question 5</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        Why are the last two lines put within brackets?\n      </div>\n      <div class=\"q-marks\">[2]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The last two lines—<em>“(For song, issuing from its birth-place, after fulfilment, wandering / Reck’d or unreck’d, duly with love returns.)”</em>—are enclosed in brackets because:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Shift in Speaker:</strong> The previous lines represent the direct dialogue spoken by the Voice of the Rain. The bracketed lines are not spoken by the rain; they are the poet’s personal philosophical reflection and concluding commentary.</li>\n        <li><strong>Literary Aside:</strong> The brackets function as an intellectual \"aside,\" drawing a conceptual analogy between the ecological cycle of rain and the artistic lifecycle of human music and poetry.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Distinction between the rain’s speech and the poet’s internal contemplation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Enclosure marks a philosophical aside comparing art and nature</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch8-q6 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch8-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch8-q6')\">\n      <div class=\"q-num\">Question 6</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        List the pairs of opposites found in the poem.\n      </div>\n      <div class=\"q-marks\">[2]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Walt Whitman employs multiple binary oppositions to reflect the comprehensive reach of nature:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>Rise and Descend:</strong> Upward motion into heaven vs. downward shower onto the globe.</li>\n        <li><strong>Day and Night:</strong> <em>“And for ever, by day and night, I give back life to my own origin.”</em></li>\n        <li><strong>Reck’d and Unreck’d:</strong> Cared for / noticed vs. uncared for / unnoticed.</li>\n        <li><strong>Latent and Unborn:</strong> Dormant under soil vs. brought to flourishing life through rain.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Rise and descend / Day and night identified</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reck’d and unreck’d / Latent and unborn identified</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(7)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 7</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(9)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 9 (Childhood) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[9] = "<section class=\"chapter-section\" id=\"c11e-ch9\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">9</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Hornbill (Poetry) &bull; Chapter 9</div>\n      <h2>Childhood</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 4 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fdf4ff, #fae8ff); border:1px solid #f0abfc; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#86198f; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#c026d3\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M8 14s1.5 2 4 2 4-2 4-2\"/><line x1=\"9\" y1=\"9\" x2=\"9.01\" y2=\"9\"/><line x1=\"15\" y1=\"9\" x2=\"15.01\" y2=\"9\"/></svg>\n      The Evolution of Maturity: Loss of Innocence\n    </h3>\n    <svg viewBox=\"0 0 800 160\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#c026d3\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#86198f\">Stanza 1: Rationalism</text>\n      <text x=\"137\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Age of Eleven</text>\n      <text x=\"137\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Heaven & Hell missing in Geography</text>\n      <text x=\"137\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Logic replaces mythology</text>\n\n      <path d=\"M 250 80 L 285 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#a21caf\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#701a75\">Stanza 2: Adult Hypocrisy</text>\n      <text x=\"397\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Social Awareness</text>\n      <text x=\"397\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Adults preach love, act harshly</text>\n      <text x=\"397\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Double standards exposed</text>\n\n      <path d=\"M 510 80 L 545 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"25\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">Stanza 3: Individuality</text>\n      <text x=\"660\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Independent Mind</text>\n      <text x=\"660\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Producing own unique thoughts</text>\n      <text x=\"660\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Freedom from herd mentality</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Think It Out & Philosophical Analysis</div>\n\n  <!-- c11e-ch9-q1 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch9-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch9-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        Identify the stanza that talks of each of the following: (i) Individuality, (ii) Rationalism, (iii) Hypocrisy.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Mapping the philosophical themes to the corresponding stanzas:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><strong>(i) Rationalism &mdash; Stanza 1:</strong>\n          <br>Reflected when the poet realizes at age eleven that <em>“Hell and Heaven / Could not be found in Geography,”</em> concluding through scientific logic that they could not physically exist.\n        </li>\n        <li><strong>(ii) Hypocrisy &mdash; Stanza 2:</strong>\n          <br>Reflected when the poet observes that adults <em>“were not all they seemed to be. / They talked of love and preached of love, / But did not act so lovingly.”</em>\n        </li>\n        <li><strong>(iii) Individuality &mdash; Stanza 3:</strong>\n          <br>Reflected when the poet discovers that his mind is completely his own: <em>“To use whichever way I choose, / Producing thoughts that were not those of other people / But my own, and mine alone.”</em>\n        </li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Rationalism correctly mapped to Stanza 1 with geography proof</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Hypocrisy correctly mapped to Stanza 2 with adult double standards</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Individuality correctly mapped to Stanza 3 with independent thinking</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch9-q2 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch9-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch9-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        What, according to the poem, is involved in the process of growing up?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Markus Natten portrays growing up not merely as biological aging, but as a three-stage psychological transformation accompanied by the loss of naive innocence:</p>\n      <ol style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Emergence of Rational Thinking:</strong> The child abandons blind belief in folklore, myths, and religious dogmas (like geographical hell and heaven) and begins evaluating reality through empirical logic and science.</li>\n        <li><strong>Recognition of Adult Hypocrisy:</strong> The growing adolescent sees through the facade of adult morality, realizing that elders preach lofty sermons about love and compassion but frequently practice hostility and deception.</li>\n        <li><strong>Assertion of Individuality:</strong> The individual develops intellectual autonomy, forming unique personal convictions rather than slavishly following herd mentality.</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Rationalism and questioning of unscientific dogmas</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Disillusionment upon discovering adult hypocrisy</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Attainment of intellectual individuality and autonomous judgment</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch9-q3 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch9-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch9-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        What are the poet’s feelings towards childhood?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The poet views childhood with deep nostalgia, reverence, and a sense of wistful loss:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Pristine Sanctuary of Innocence:</strong> He regards childhood as a magical, uncorrupted period of existence free from deceit, cynicism, and inner contradictions.</li>\n        <li><strong>Wistful Yearning:</strong> While he values the rational intellect and individuality that accompany adulthood, he mourns the irrevocable loss of childlike simplicity and wonder.</li>\n        <li><strong>Consolation:</strong> He takes comfort in knowing that childhood has not vanished into absolute nothingness; it remains immortalized in the pure, untainted smile on an infant’s face.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Nostalgia for pure innocence free from adult cynicism</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Wistful longing acknowledging that lost childhood cannot return</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Philosophical solace finding childhood preserved in an infant’s face</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch9-q4 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch9-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch9-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        Which, do you think, are the most poetic lines? Why?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The concluding lines of the poem are widely regarded as the most poetic and evocative:</p>\n      <blockquote style=\"margin:8px 0; padding:8px 16px; background:#fdf4ff; border-left:4px solid #c026d3; font-style:italic;\">\n        “It went to some forgotten place,<br>\n        That’s hidden in an infant’s face,<br>\n        That’s all I know.”\n      </blockquote>\n      <p><strong>Critical Rationale:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Shift from ‘When’ to ‘Where’:</strong> Across the first three stanzas, the poet repeatedly asks the temporal question: <em>“When did my childhood go?”</em> In this final stanza, he pivots to the spatial question: <em>“Where did my childhood go?”</em></li>\n        <li><strong>Lyrical Imagery:</strong> Instead of offering a dry philosophical answer, the poet captures the essence of innocence through the tender, concrete image of an infant’s face.</li>\n        <li><strong>Universal Truth:</strong> It highlights that childhood is not lost forever; it is reborn continuously in every new generation of infants, leaving the reader with a poignant, lingering sense of peace.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Quoting the final three lines as the most poetic climax</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Structural shift from \"When did it go\" to \"Where did it go\"</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Lyrical imagery of the infant’s face representing reborn innocence</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(8)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 8</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(10)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 10 (Father to Son) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[10] = "<section class=\"chapter-section\" id=\"c11e-ch10\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">10</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Hornbill (Poetry) &bull; Chapter 10</div>\n      <h2>Father to Son</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 4 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #f8fafc, #fee2e2); border:1px solid #fecaca; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#991b1b; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"2\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\n      The Generation Gap: Emotional Alienation Under One Roof\n    </h3>\n    <svg viewBox=\"0 0 800 160\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"30\" y=\"25\" width=\"220\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"140\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#991b1b\">The Father’s World</text>\n      <text x=\"140\" y=\"80\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Traditional Nostalgia</text>\n      <text x=\"140\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Yearns for prodigal’s return</text>\n      <text x=\"140\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Built child to his design</text>\n\n      <path d=\"M 255 80 L 335 80\" stroke=\"#94a3b8\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <circle cx=\"295\" cy=\"80\" r=\"14\" fill=\"#fee2e2\" stroke=\"#dc2626\" stroke-width=\"1.5\"/>\n      <text x=\"295\" y=\"84\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#dc2626\">✕</text>\n\n      <rect x=\"335\" y=\"25\" width=\"220\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <text x=\"445\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#334155\">The Chasm: Silence</text>\n      <text x=\"445\" y=\"80\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Communication Barrier</text>\n      <text x=\"445\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Speak like strangers</text>\n      <text x=\"445\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Seed spent in alien land</text>\n\n      <path d=\"M 560 80 L 640 80\" stroke=\"#94a3b8\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n\n      <rect x=\"640\" y=\"25\" width=\"130\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"705\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#0369a1\">The Son’s World</text>\n      <text x=\"705\" y=\"80\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Independent</text>\n      <text x=\"705\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Modern values</text>\n      <text x=\"705\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Silent sorrow</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Think It Out & Thematic Analysis</div>\n\n  <!-- c11e-ch10-q1 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch10-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch10-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        Does the poem talk of an exclusively personal experience or is it fairly universal?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The poem does not narrate an exclusively personal experience; rather, it articulates a <strong>fairly universal human predicament</strong>.</p>\n      <p><strong>Reasons for Universality:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>The Generation Gap:</strong> The emotional estrangement, inability to communicate, and conflict of values between aging parents and grown-up children is a widespread phenomenon across families and cultures worldwide.</li>\n        <li><strong>Parental Incomprehension:</strong> Parents frequently expect their offspring to mirror their own beliefs, design, and choices. When children grow into autonomous individuals with distinct worldviews, parents feel bewildered and isolated.</li>\n        <li><strong>Universal Yearning for Reconciliation:</strong> The father's desperate struggle to reach out, forgive, and bridge the gulf with extended \"empty hands\" mirrors the silent longing of countless parents across human society.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmation that the poem deals with a universal generation gap</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Analysis of parental expectation vs children’s autonomous identity</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Universal emotional desire for reconciliation across families</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch10-q2 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch10-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch10-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        How is the father’s helplessness brought out in the poem?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Elizabeth Jennings poignantly portrays the father’s profound helplessness and emotional grief:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Strangers Under One Roof:</strong> Despite having lived in the same house for years, the father confesses with profound agony: <em>“I do not understand this child... I know nothing of him.”</em> They speak like strangers with no sign of understanding in the air.</li>\n        <li><strong>Loss of Influence:</strong> He acknowledges that while the child is physically <em>“built to my design,”</em> what his son loves in his heart, the father cannot share or comprehend.</li>\n        <li><strong>Inability to Prevent Estrangement:</strong> He longs to welcome his son back like the biblical \"prodigal son\" and forgive him unconditionally rather than see him build a separate, alien world. Yet, his inability to articulate this love results in an icy, suffocating silence.</li>\n        <li><strong>The Empty Hands:</strong> In the final heartbreaking image, both father and son stand with <em>“empty hands,”</em> longing for something to forgive, yet paralyzed by pride and misunderstanding.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Confession of knowing nothing of his own son despite living together</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Inability to share or understand the son’s modern interests</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Tragic inability to break the silence, ending with outstretched empty hands</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch10-q3 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch10-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch10-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        Identify the phrases and lines that indicate the distance between father and son.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The emotional and physical chasm between father and son is articulated through key phrases:</p>\n      <ul style=\"margin-left:20px; line-height:1.8;\">\n        <li><em>“I do not understand this child”</em> &mdash; Highlights the complete failure of parental comprehension.</li>\n        <li><em>“I know / Nothing of him”</em> &mdash; Highlights total emotional detachment.</li>\n        <li><em>“We speak like strangers”</em> &mdash; Highlights the loss of familial intimacy.</li>\n        <li><em>“There’s no sign of understanding in the air”</em> &mdash; Conveys an atmosphere devoid of empathy.</li>\n        <li><em>“Yet what he loves I cannot share”</em> &mdash; Marks the divergence in tastes, values, and lifestyle.</li>\n        <li><em>“Silence surrounds us”</em> &mdash; Symbolizes the oppressive, suffocating absence of communication.</li>\n        <li><em>“Each puts out an empty hand, / Longing for something to forgive”</em> &mdash; Depicts unfulfilled emotional yearning blocked by pride.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of \"I do not understand\" and \"We speak like strangers\"</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of \"Silence surrounds us\" and \"what he loves I cannot share\"</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of \"Each puts out an empty hand\" concluding the estrangement</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch10-q4 (Think It Out) -->\n  <div class=\"q-card\" id=\"c11e-ch10-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch10-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Think It Out</span><br>\n        Does the poem have a consistent rhyme scheme? What is the structural significance?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p><strong>Rhyme Scheme Analysis:</strong></p>\n      <p>The poem does not follow a completely consistent or uniform rhyme scheme across all stanzas:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li>The early stanzas loosely follow an <strong><code>ab ba ba</code></strong> or alternating end-rhyme pattern (e.g., child/build, year/share, air/there).</li>\n        <li>As the emotional tension mounts in later stanzas, the rhyme structure becomes irregular, shifting to <strong><code>abc aba</code></strong> and <strong><code>abbcb</code></strong> schemes with near rhymes and half-rhymes.</li>\n      </ul>\n      <p><strong>Structural Significance:</strong></p>\n      <p>This irregular, slightly fractured rhyme scheme is intentional. It artistically mirrors the fractured, disrupted relationship between the father and the son. The lack of strict metric harmony echoes the discord, lack of rhythm, and broken communication in their home.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identified rhyme scheme as loose and irregular across stanzas</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Examples of half-rhymes and shifting line patterns</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Structural significance: Fractured rhyme mirroring fragmented relationship</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(9)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 9</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(11)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 11 (The Summer of the Beautiful White Horse) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[11] = "<section class=\"chapter-section\" id=\"c11e-ch11\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">11</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Snapshots (Supplementary Reader) &bull; Chapter 11</div>\n      <h2>The Summer of the Beautiful White Horse</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 4 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #f0fdf4, #ecfdf5); border:1px solid #a7f3d0; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#065f46; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"m4.93 4.93 4.24 4.24\"/><path d=\"m14.83 9.17 4.24-4.24\"/><path d=\"m14.83 14.83 4.24 4.24\"/><path d=\"m9.17 14.83-4.24 4.24\"/></svg>\n      The Moral Dilemma: Garoghlanian Honor vs Childhood Passion\n    </h3>\n    <svg viewBox=\"0 0 800 160\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">Tribal Heritage</text>\n      <text x=\"137\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Garoghlanian Honor</text>\n      <text x=\"137\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• 11 centuries of unblemished honesty</text>\n      <text x=\"137\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Extreme, comical poverty</text>\n\n      <path d=\"M 250 80 L 285 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d97706\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#b45309\">Childhood Temptation</text>\n      <text x=\"397\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">The Crazy Streak</text>\n      <text x=\"397\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Passionate craze for horse riding</text>\n      <text x=\"397\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"Stealing for riding isn’t theft\"</text>\n\n      <path d=\"M 510 80 L 545 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"25\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#2563eb\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#1d4ed8\">Moral Awakening</text>\n      <text x=\"660\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">John Byro’s Trust</text>\n      <text x=\"660\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Byro refuses to suspect honesty</text>\n      <text x=\"660\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Secretly return horse at dawn</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Reading with Insight</div>\n\n  <!-- c11e-ch11-q1 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch11-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch11-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        You will probably agree that this story does not have breathless adventure and exciting action. Then what in your opinion makes it interesting?\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>While the story lacks high-octane violence, espionage, or perilous physical adventures, it is profoundly engaging, warm, and delightful for several literary reasons:</p>\n      <ol style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Nostalgic Childhood Perspective:</strong> Narrated from the perspective of nine-year-old Aram, the story captures the enchanting innocence of a world that was <em>“full of every imaginable kind of magnificence, and life was still a delightful and mysterious dream.”</em></li>\n        <li><strong>Authentic Child Psychology:</strong> The boys’ childish rationalization—that stealing a horse to ride was not the same as stealing money because they never intended to sell it—rings psychologically true and humorous.</li>\n        <li><strong>Eccentric and Colorful Characters:</strong> The \"crazy streak\" in the family provides rich humor, particularly through Uncle Khosrove with his booming temper and universal dismissal: <em>“It is no harm; pay no attention to it!”</em>, even when his own house was burning down.</li>\n        <li><strong>Poignant Moral Conflict:</strong> The quiet tension between the boys’ desperate longing for horses and their unyielding pride in their tribe’s eleven centuries of unblemished honesty creates a subtle, emotionally satisfying climax.</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Nostalgic childhood perspective and lyrical atmosphere</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Insight into child psychology and humorous moral rationalizations</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Comical eccentricity of Uncle Khosrove and cousin Mourad</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Quiet moral dilemma between tribal honesty and youthful temptation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch11-q2 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch11-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch11-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        Did the boys return the horse because they were conscience-stricken or because they were afraid?\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The boys returned the horse because they were <strong>conscience-stricken</strong>, not out of fear of punishment or detection.</p>\n      <p><strong>Detailed Literary Evidence:</strong></p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>No Fear of Discovery:</strong> The boys had successfully hidden the beautiful white horse in the deserted vineyard of farmer Fetvajian for weeks, riding it every morning at daybreak. Nobody suspected them because the Garoghlanian tribe was universally renowned for honesty.</li>\n        <li><strong>The Encounter with John Byro:</strong> When the boys met the horse’s rightful owner, John Byro, on the road, Byro examined the horse closely, looked into its mouth tooth by tooth, and remarked: <em>“I would swear it is my horse if I didn’t know your parents. The fame of your family for honesty is well known to me. Yet the horse is the twin of my horse.”</em></li>\n        <li><strong>The Prick of Conscience:</strong> John Byro’s noble refusal to accuse them, solely out of profound respect for their family’s proud heritage of integrity, pierced their conscience deeply. They realized that keeping the horse would permanently tarnish their family's unblemished eleven-hundred-year reputation. The very next morning, they took the horse to John Byro’s vineyard and tied it in the barn.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear assertion that return was driven by conscience, not fear</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Proof that the horse was securely hidden and suspicion was zero</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">John Byro’s unconditional trust in their family honesty acting as catalyst</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conscious decision to protect tribal honor over personal pleasure</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch11-q3 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch11-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch11-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        “One day back there in the good old days when I was nine and the world was full of every imaginable kind of magnificence, and life was still a delightful and mysterious dream...” The story begins in a mood of nostalgia. Can you narrate some incident from your childhood that brings back memories like these?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>This opening line evokes the timeless magic of early childhood, when reality is bathed in wonder and simple adventures assume epic grandeur.</p>\n      <p><strong>Personal Reflective Narrative (Sample Model Response):</strong></p>\n      <blockquote style=\"margin:8px 0; padding:10px 16px; background:#f0fdf4; border-left:4px solid #059669; font-style:italic;\">\n        “This line transports me back to my seventh summer, when my cousins and I spent our holidays at my grandfather’s ancestral village home. One twilight evening, we discovered an abandoned, overgrown orchard behind the cow sheds. To our young imaginations, that tangled thicket of guava trees was an uncharted enchanted forest. We fashioned wooden swords from fallen branches, christened an old rusty bullock cart as our royal chariot, and spent hours chasing fireflies across the moonlit fields. There were no cellphones, no academic pressures, and no anxieties about the future—the world was infinitely large, safe, and brimming with innocence. Just as Aram and Mourad felt flying through walnut orchards in the cool dawn air, that summer remains an indelible dream of pure happiness.”\n      </blockquote>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Appreciation of Aram’s nostalgic opening sentiment</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Coherent personal narrative recounting a childhood memory of wonder</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Thematic correlation connecting innocence, imagination and simple joys</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch11-q4 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch11-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch11-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        Describe the distinctive traits of Mourad and Uncle Khosrove that show they shared the family’s “crazy streak”.\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>In the Garoghlanian tribe, individual character was believed to descend directly from spiritual ancestors rather than biological fathers. Both Mourad and Uncle Khosrove were living embodiments of the family’s eccentric \"crazy streak\":</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Uncle Khosrove’s Eccentricities:</strong> An enormous man with a roaring voice and a bushy black moustache. He was notoriously impatient, irritable, and furious, silencing all human dialogue with his trademark roar: <em>“It is no harm; pay no attention to it!”</em> When his son Arak ran eight blocks to tell him their house was on fire, Khosrove simply roared: <em>“Enough! It is no harm, I say!”</em> When John Byro mourned his stolen horse, Khosrove roared that losing a horse was trivial compared to losing their homeland.</li>\n        <li><strong>Mourad’s Crazy Streak:</strong> Viewed as the natural descendant of Khosrove’s mania. He lived with wild, fearless abandon, sang or roared lustily while galloping bareback on the horse at 4 a.m., and claimed to have <em>“a way with horses, a way with dogs, and a way with birds.”</em> He nursed an injured young robin's broken wing back to health and talked to animals with serene confidence.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of tribal theory of hereditary \"crazy streaks\"</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Khosrove’s traits: booming voice, impatience, universal dismissal of disasters</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mourad’s traits: wild abandon, morning horse rides, mystical affinity with animals</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(10)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 10</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(12)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 12 (The Address) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[12] = "<section class=\"chapter-section\" id=\"c11e-ch12\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">12</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Snapshots (Supplementary Reader) &bull; Chapter 12</div>\n      <h2>The Address</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 4 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #f8fafc, #f1f5f9); border:1px solid #cbd5e1; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#334155; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#475569\" stroke-width=\"2\"><path d=\"m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/><polyline points=\"9 22 9 12 15 12 15 22\"/></svg>\n      The Psychological Burden of Possessions: Number 46, Marconi Street\n    </h3>\n    <svg viewBox=\"0 0 800 160\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#64748b\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#334155\">Pre-War Home</text>\n      <text x=\"137\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Beloved Belongings</text>\n      <text x=\"137\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Silver cutlery, Hanukkah lamp</text>\n      <text x=\"137\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Mother entrusts to Mrs. Dorling</text>\n\n      <path d=\"M 250 80 L 285 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#b91c1c\">Post-War Reality</text>\n      <text x=\"397\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Alienated Treasures</text>\n      <text x=\"397\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Objects used tastelessly</text>\n      <text x=\"397\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Cold rejection by Mrs. Dorling</text>\n\n      <path d=\"M 510 80 L 545 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"25\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#047857\">Liberation / Renunciation</text>\n      <text x=\"660\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Severing Ties</text>\n      <text x=\"660\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Things lose value without loved ones</text>\n      <text x=\"660\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Resolve to forget the address</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Reading with Insight</div>\n\n  <!-- c11e-ch12-q1 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch12-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch12-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        “Have you come back?” said the woman, “I thought that no one had come back.” Does this statement give some clue about the story? If yes, what is it?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Yes, this blunt, inhospitable opening statement provides profound clues about the story’s socio-historical context and human drama:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>The Context of the Holocaust:</strong> The setting is Holland during and after World War II. The narrator and her mother were Dutch Jews persecuted by the Nazi regime. The woman, Mrs. Dorling, had assumed that the entire family had perished in Nazi concentration camps, as happened to millions of European Jews.</li>\n        <li><strong>Human Greed and Betrayal:</strong> Mrs. Dorling took custody of all the valuable antique furniture, crockery, cutlery, and silverware under the pretext of \"safekeeping.\" Her disappointment upon seeing the daughter alive betrays her covetousness—she had usurped these treasures as her own and felt threatened that someone had survived to reclaim them.</li>\n        <li><strong>Sets the Emotional Tone:</strong> It establishes the cold indifference and lack of basic human sympathy that greeted surviving Jewish refugees upon returning to their homelands.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clue identifying World War II, Nazi occupation and Holocaust extermination</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Exposure of Mrs. Dorling’s greed assuming the owners were dead</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Insight into post-war isolation and indifference faced by survivors</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch12-q2 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch12-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch12-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        The story is divided into pre-war and post-war times. What hardships do you think the girl underwent during these times?\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Marga Minco’s understated prose reveals intense psychological and physical trauma across both eras:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Pre-War Hardships:</strong>\n          <br>The girl and her mother lived under the terrifying shadow of Nazi persecution, facing curfew restrictions, yellow star mandates, and the constant threat of deportation. They suffered the agonizing distress of seeing their cherished ancestral home dismantled piece by piece, as Mrs. Dorling carried away heavy suitcases filled with silver and antiques, while the mother lived in constant dread of an impending raid.\n        </li>\n        <li><strong>Post-War Hardships:</strong>\n          <br>The narrator survived the war entirely alone—her mother, family, and former life were eradicated. She lived in a bleak, tiny rented room with blackout paper peeling from the windows. When she attempted to reconnect with her past by visiting Number 46, Marconi Street, she was met with cold hostility by Mrs. Dorling. Entering the house on a second visit, she found her mother’s prized belongings displayed tasteless and misused in an alien living room, re-traumatizing her with grief and alienation.\n        </li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Pre-war fear of arrest, persecution and seeing home dismantled</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Post-war total bereavement, loneliness in rented room, and traumatic reunion</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch12-q3 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch12-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch12-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        Why did the narrator of the story want to forget the address?\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The narrator resolved to erase <strong>Number 46, Marconi Street</strong> from her memory because holding onto it prolonged futile pain:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Severed Emotional Connection:</strong> Possessions derive their emotional soul and beauty from the living context of the loved ones who used them. Stripped of her mother’s gentle touch and placed in Mrs. Dorling’s tasteless, stuffy room, the objects looked mutilated and severed from their past.</li>\n        <li><strong>Impracticality of Material Possessions:</strong> The narrator lived in a tiny rented room with narrow cutlery drawers. She had no space or practical use for heavy silver sets, pewter plates, or elaborate tea services.</li>\n        <li><strong>Psychological Liberation:</strong> Reclaiming the objects could never bring back her mother or resurrect her lost youth. To cling to the address meant remaining imprisoned by grief, resentment, and bitterness. Forgetting the address was an act of mature emotional liberation, enabling her to make a clean break with the past and move forward.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Loss of emotional soul of objects when placed in strange surroundings</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Lack of physical space in tiny rented room for opulent antique items</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Psychological decision to move on rather than nurse bitter grief</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch12-q4 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch12-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch12-q4')\">\n      <div class=\"q-num\">Question 4</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        “The Address” is a story of human predicament that follows war. Comment.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Minco’s narrative is a poignant exploration of the profound, invisible wounds inflicted by war on the human psyche:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Beyond Physical Destruction:</strong> While war history often documents battle deaths and ruined cities, it rarely records the quiet tragedy of the survivors—individuals left uprooted, emotionally bankrupt, and isolated in empty landscapes.</li>\n        <li><strong>Moral Erosion:</strong> War brings out predatory selfishness in acquaintances (like Mrs. Dorling), who feign friendship to opportunistically loot the possessions of vulnerable families facing extermination.</li>\n        <li><strong>The Futility of Clinging to the Past:</strong> The survivor realizes that material relics cannot substitute for living relationships. True healing begins only when the victim courageously relinquishes physical attachments and accepts that the pre-war world is irretrievably gone.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Focus on the invisible emotional trauma of war survivors</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Exposure of moral degradation and opportunistic looting during crisis</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">The necessity of renouncing material baggage to heal post-war trauma</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(11)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 11</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(13)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 13 (Albert Einstein at School) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[13] = "<section class=\"chapter-section\" id=\"c11e-ch13\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">13</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Snapshots (Supplementary Reader) &bull; Chapter 13</div>\n      <h2>Albert Einstein at School</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 3 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fef3c7, #fff7ed); border:1px solid #fed7aa; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#9a3412; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#ea580c\" stroke-width=\"2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      Education Philosophy: Rote Learning vs Scientific Insight\n    </h3>\n    <svg viewBox=\"0 0 800 160\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#b91c1c\">Prussian Rote System</text>\n      <text x=\"137\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">History Teacher Braun</text>\n      <text x=\"137\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Memorizing dates of battles</text>\n      <text x=\"137\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Unquestioning conformity</text>\n\n      <path d=\"M 250 80 L 285 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#ea580c\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#c2410c\">Einstein’s Philosophy</text>\n      <text x=\"397\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Ideas over Information</text>\n      <text x=\"397\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"Why men killed each other\"</text>\n      <text x=\"397\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• One can look up dates in books</text>\n\n      <path d=\"M 510 80 L 545 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"25\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#047857\">Mathematical Genius</text>\n      <text x=\"660\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Teacher Mr. Koch</text>\n      <text x=\"660\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"Albert can teach me mathematics\"</text>\n      <text x=\"660\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Ready for university entry</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Reading with Insight</div>\n\n  <!-- c11e-ch13-q1 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch13-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch13-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        What do you understand of Einstein’s nature from his conversations with his history teacher, his mathematics teacher and the head teacher?\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Albert Einstein emerges as a fiercely honest, intellectually independent, and non-conformist genius who despised regimented authority:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>With the History Teacher (Mr. Braun):</strong>\n          <br>Albert is brutally honest and intellectually unapologetic. When asked the date of the Battle of Waterloo, he calmly admits he doesn't know and doesn't see the point in memorizing facts that can easily be looked up in a book. He politely asserts his conviction that education should focus on <em>ideas and underlying causes</em> (why soldiers fought) rather than dead historical dates, refusing to yield even when mocked.\n        </li>\n        <li><strong>With the Mathematics Teacher (Mr. Koch):</strong>\n          <br>Shows immense respect, intellectual humility, and exceptional brilliance. Mr. Koch admires Albert, recognizing that Albert already knows more mathematics than the high school syllabus teaches. Albert respectfully requests a reference letter to enter an Italian university without showing arrogant condescension.\n        </li>\n        <li><strong>With the Head Teacher:</strong>\n          <br>When the headmaster abruptly expels him—claiming Albert’s presence disrupts discipline and prevents teachers from teaching—Albert refuses to plead, argue, or demean himself. He maintains quiet, stoic dignity, resisting the urge to express his true disdain, and walks out of the school with head held high without looking back.\n        </li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">History teacher: Frank honesty, critical thinking over rote facts</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mathematics teacher: Mutual respect, intellectual brilliance and humility</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Head teacher: Calm dignity, refusal to grovel, pride under unjust expulsion</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch13-q2 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch13-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch13-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        The school system often curbs individual talents. Discuss.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The chapter offers a trenchant critique of rigid, one-size-fits-all education systems that stifle creative genius:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Tyranny of Rote Memorization:</strong> Traditional schooling equates intelligence with mechanical recall of facts, dates, and formulas. Students who think critically, question fundamental assumptions, or ask \"why\" are branded as troublemakers or insolent rebels.</li>\n        <li><strong>Suppression of Originality:</strong> Standardized curricula force every child into identical molds, penalizing those whose passions lie outside orthodox syllabi (as Einstein was chastised for reading advanced geology and physics books not taught in school).</li>\n        <li><strong>Authoritarian Discipline:</strong> The Prussian school system depicted in Munich emphasized militaristic blind obedience rather than nurturing intellectual curiosity. It alienated the greatest scientific mind of the 20th century to the point of a nervous breakdown.</li>\n        <li><strong>Conclusion:</strong> Modern education must celebrate diverse intelligences, encouraging inquiry-based learning, problem-solving, and lateral thinking over mechanical examination results.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Critique of rote learning and memorization over understanding</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Punishment of intellectual non-conformity and questioning spirit</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Call for modern student-centric, inquiry-based educational paradigms</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch13-q3 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch13-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch13-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        How do you distinguish between information gathering and insight formation?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Einstein’s dialogue with Mr. Braun draws a profound distinction between superficial knowledge and deep intellectual comprehension:</p>\n      <table style=\"width:100%; border-collapse:collapse; margin-top:12px; margin-bottom:12px; font-size:0.95rem;\">\n        <thead>\n          <tr style=\"background:#f1f5f9; text-align:left;\">\n            <th style=\"padding:10px; border:1px solid #cbd5e1;\">Information Gathering</th>\n            <th style=\"padding:10px; border:1px solid #cbd5e1;\">Insight Formation</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">Mechanical collection and memorization of external facts, dates, statistics, and formulas.</td>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">Deep cognitive understanding of underlying causes, patterns, relationships, and principles.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">Static and easily accessible—can be looked up in books, encyclopedias, or online search engines.</td>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">Dynamic and creative—requires critical reasoning, analytical inquiry, and conceptual synthesis.</td>\n          </tr>\n          <tr>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">Example: Memorizing that the Prussians defeated the French at Waterloo in 1815.</td>\n            <td style=\"padding:10px; border:1px solid #cbd5e1;\">Example: Analyzing why armies fought, the political ideologies involved, and the human cost.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>True education is not the learning of facts, but the training of the mind to think and formulate original insights.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clear definition of information gathering as passive factual recall</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of insight formation as analytical, conceptual synthesis</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Textual reference to Einstein’s Waterloo example and educational philosophy</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(12)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 12</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(14)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 14 (Mother's Day) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[14] = "<section class=\"chapter-section\" id=\"c11e-ch14\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">14</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Snapshots (Supplementary Reader) &bull; Chapter 14</div>\n      <h2>Mother's Day</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 3 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #fdf2f8, #fce7f3); border:1px solid #fbcfe8; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#9d174d; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#db2777\" stroke-width=\"2\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M22 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\n      The Pearson Revolution: Personality Swap & Domestic Reform\n    </h3>\n    <svg viewBox=\"0 0 800 160\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#db2777\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#9d174d\">Domestic Exploitation</text>\n      <text x=\"137\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Meek Mrs. Pearson</text>\n      <text x=\"137\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Treated as an unpaid servant</text>\n      <text x=\"137\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Husband & children order her</text>\n\n      <path d=\"M 250 80 L 285 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#9333ea\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#7e22ce\">The Radical Catalyst</text>\n      <text x=\"397\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Mrs. Fitzgerald's Magic</text>\n      <text x=\"397\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"Body swap\" occult spell</text>\n      <text x=\"397\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Smokes, drinks, speaks home truths</text>\n\n      <path d=\"M 510 80 L 545 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"25\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#065f46\">Domestic Harmony</text>\n      <text x=\"660\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Mutual Respect</text>\n      <text x=\"660\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Family serves dinner together</text>\n      <text x=\"660\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Family game of rummy</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Reading with Insight</div>\n\n  <!-- c11e-ch14-q1 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch14-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch14-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        This play, written in the 1950s, is a humorous and satirical depiction of the status of the mother in a family. What are the issues it raises? Do you think it has outlived its utility?\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>J.B. Priestley’s witty play addresses persistent social issues surrounding domestic gender inequality:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Unpaid and Unappreciated Domestic Labor:</strong> Mrs. Pearson works eight hours a day, seven days a week, cooking, ironing, cleaning, and waiting on her family hand and foot without receiving a single word of thanks, financial compensation, or a weekend off.</li>\n        <li><strong>Taking Mothers for Granted:</strong> Her husband George and children Doris and Cyril treat the house as a luxury hotel, dropping in only to demand tea, demanding clothes be mended, and rushing out to their social clubs while abandoning their mother in solitary neglect.</li>\n        <li><strong>Has it Outlived its Utility?</strong>\n          <br><strong>No, it has certainly NOT outlived its utility.</strong> Even in contemporary 21st-century society, working and homemaking mothers alike carry an inequitable \"second shift\" of domestic chores and mental labor. The systemic expectation that mothers must selflessly sacrifice their personal leisure, dignity, and autonomy remains painfully prevalent worldwide.\n        </li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of unpaid domestic labor and continuous 7-day work week</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Analysis of family taking the mother’s care for granted without gratitude</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Persuasive argument proving the play remains highly relevant today</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch14-q2 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch14-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch14-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        Is drama a good medium for conveying a social message? Discuss.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Drama is uniquely powerful and persuasive for delivering sharp social critiques:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Immediate Emotional & Visual Impact:</strong> Unlike a dry essay or political speech, drama embodies ideas through living human characters. Watching Doris burst into tears or George cower in embarrassment makes the audience viscerally experience the absurdity of domestic arrogance.</li>\n        <li><strong>The Disarming Power of Satire and Humor:</strong> Priestley uses comedy and the fantastical body-swap device to make serious social injustices palpable. Humor disarms the audience’s defenses, allowing them to laugh at the Pearsons while simultaneously recognizing their own selfish domestic behavior.</li>\n        <li><strong>Cathartic Resolution:</strong> Drama allows the audience to witness an immediate before-and-after transformation. Seeing the reformed family humbly serve their mother tea and play rummy provides a clear, practical blueprint for domestic reform.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Visual and emotional immediacy of dramatic dialogue over dry essays</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Satire and comedy disarming audience defenses to deliver home truths</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Practical demonstration of reform through theatrical climax</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch14-q3 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch14-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch14-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        The play portrays the situation in a British suburban home. Has Indian society changed enough for Indian mothers to relate to Mrs. Pearson?\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>An exploration of cross-cultural relevance in contemporary Indian society:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Profound Resonance with Indian Mothers:</strong> The plight of Mrs. Pearson resonates deeply with the traditional reality of millions of Indian households, where the mother is often eulogized as a selfless deity (<em>“Annapurna”</em> or <em>“Devi”</em>) precisely to justify her domestic servitude. Indian mothers frequently wake up earliest, sleep latest, eat after everyone has eaten, and rarely get personal leisure time.</li>\n        <li><strong>Signs of Gradual Evolution:</strong> In modern urban educated homes, there is growing feminist awareness. Husbands and children increasingly share kitchen chores, clean dishes, and support mothers pursuing independent careers and hobbies.</li>\n        <li><strong>Persistent Reality:</strong> Despite surface changes, the deep-seated patriarchal conditioning that household management is fundamentally the woman’s responsibility remains prevalent in many Indian households, making Mrs. Pearson’s awakening relatable to Indian audiences.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Deep resonance with traditional Indian homemakers eulogized into servitude</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Signs of modern progress in urban households sharing chores</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conclusion confirming strong cultural relatability in contemporary India</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(13)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 13</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(15)\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; cursor:pointer;\">Next: Ch 15 (Birth) →</button>\n  </div>\n</section>";

window.CHAPTER_DATA[15] = "<section class=\"chapter-section\" id=\"c11e-ch15\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\" style=\"background:#4338ca;\">15</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\" style=\"color:#4338ca;\">CBSE Class 11 English Core &bull; Snapshots (Supplementary Reader) &bull; Chapter 15</div>\n      <h2>Birth</h2>\n      <p>NCERT Rationalised 2026–27 Syllabus &bull; All 3 Verbatim Questions with Official Step-by-Step Marking Rubrics</p>\n    </div>\n  </div>\n\n  \n  <div style=\"background:linear-gradient(135deg, #f0fdf4, #e0f2fe); border:1px solid #bae6fd; border-radius:12px; padding:20px; margin-bottom:24px;\">\n    <h3 style=\"font-size:1.05rem; color:#0369a1; margin-bottom:12px; font-weight:800; display:flex; align-items:center; gap:8px;\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#0284c7\" stroke-width=\"2\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg>\n      The Resuscitation Protocol: Dr. Andrew Manson’s Miracle at Midnight\n    </h3>\n    <svg viewBox=\"0 0 800 160\" style=\"width:100%; height:auto; font-family:'Plus Jakarta Sans', sans-serif;\">\n      <rect x=\"25\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dc2626\" stroke-width=\"2\"/>\n      <text x=\"137\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#b91c1c\">Dual Medical Emergency</text>\n      <text x=\"137\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Number 12, Blaina Terrace</text>\n      <text x=\"137\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Mother Susan collapsing</text>\n      <text x=\"137\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Stillborn child under bed</text>\n\n      <path d=\"M 250 80 L 285 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"285\" y=\"25\" width=\"225\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#0284c7\" stroke-width=\"2\"/>\n      <text x=\"397\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#0369a1\">Hydrotherapy Protocol</text>\n      <text x=\"397\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Asphyxia Pallida</text>\n      <text x=\"397\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Two basins: Icy cold & hot water</text>\n      <text x=\"397\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Plunges baby alternately</text>\n\n      <path d=\"M 510 80 L 545 80\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n\n      <rect x=\"545\" y=\"25\" width=\"230\" height=\"110\" rx=\"8\" fill=\"#ffffff\" stroke=\"#059669\" stroke-width=\"2\"/>\n      <text x=\"660\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#047857\">The Spark of Life</text>\n      <text x=\"660\" y=\"78\" text-anchor=\"middle\" font-size=\"11\" fill=\"#475569\">Triumph of Science</text>\n      <text x=\"660\" y=\"100\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• Chest heaves, baby cries aloud</text>\n      <text x=\"660\" y=\"118\" text-anchor=\"middle\" font-size=\"10\" fill=\"#64748b\">• \"I’ve done something real at last!\"</text>\n    </svg>\n  </div>\n\n  <div class=\"ex-div\">NCERT Exercises: Reading with Insight</div>\n\n  <!-- c11e-ch15-q1 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch15-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch15-q1')\">\n      <div class=\"q-num\">Question 1</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        “I have done something; oh, God! I’ve done something real at last.” Why does Andrew say this? What does it mean?\n      </div>\n      <div class=\"q-marks\">[4]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Dr. Andrew Manson exclaims these immortal words at daybreak following an agonizing, miraculous battle for life:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Why Andrew Says This:</strong>\n          <br>Called to attend Joe Morgan’s wife Susan delivering their first child after twenty years of marriage, Andrew faced an acute crisis. The mother was collapsing from post-partum shock, and the infant was born lifeless, pale, and limp—a victim of <em>asphyxia pallida</em>. After stabilizing the mother, Andrew pulled the seemingly dead child from beneath dirty sodden sods under the bed. For nearly an hour, in freezing sweat and physical exhaustion, he plunged the baby alternately between basins of steaming hot and ice-cold water, rubbed it with a rough towel, and applied artificial respiration until a sudden heave filled the lungs and the baby let out a hearty cry.\n        </li>\n        <li><strong>What it Means:</strong>\n          <br>This exclamation marks Andrew's transition from a naive, textbook medical graduate into a true doctor. Previously plagued by self-doubt, romantic disillusionment, and professional insecurity, saving two human lives through instinctive brilliance gave his existence genuine meaning and purpose. He had achieved something profoundly \"real\" and noble that transcended theoretical examinations.\n        </li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Clinical context: Reviving stillborn infant born with asphyxia pallida</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Exhausting medical intervention: alternate hot and cold immersion</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Philosophical meaning: Transformation from insecure student into true healer</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch15-q2 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch15-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch15-q2')\">\n      <div class=\"q-num\">Question 2</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        There lies a great difference between textbook medicine and the world of a practising physician. Discuss.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>The chapter illustrates the vast chasm between theoretical medical textbooks and practical clinical realities:</p>\n      <ul style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Limitations of Theory in Emergencies:</strong> Medical textbooks provide sterile, step-by-step diagnostic algorithms under ideal laboratory conditions. In practical life, doctors confront chaotic, under-equipped environments (like the cramped, dim bedroom of an impoverished Welsh miner's cottage with no electricity or modern incubators).</li>\n        <li><strong>Split-Second Clinical Instinct:</strong> Andrew faced an agonizing moral dilemma—save the dying mother or attempt to revive the lifeless child. No textbook could make that choice for him; clinical instinct dictated saving the mother first, then fighting for the infant.</li>\n        <li><strong>Improvisation & Sheer Will:</strong> When orthodox methods failed, Andrew recalled an experimental method of treating asphyxia pallida he had once observed in a Samaritan hospital. Using two kitchen basins of hot and cold water and rough towels, his physical endurance and refusal to concede to death achieved what textbook protocol deemed impossible.</li>\n      </ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Contrast between sterile academic textbook theory and messy emergency conditions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Necessity of moral decision-making and prioritizing between two critical patients</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of clinical improvisation, observation and sheer physical endurance</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- c11e-ch15-q3 (Reading with Insight) -->\n  <div class=\"q-card\" id=\"c11e-ch15-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c11e-ch15-q3')\">\n      <div class=\"q-num\">Question 3</div>\n      <div class=\"q-text\">\n        <span style=\"display:inline-block; font-size:0.75rem; font-weight:800; text-transform:uppercase; background:#eef2ff; color:#4338ca; padding:2px 8px; border-radius:4px; margin-bottom:4px;\">Reading with Insight</span><br>\n        Describe the precise steps taken by Dr. Andrew Manson to revive the lifeless baby born to Susan Morgan.\n      </div>\n      <div class=\"q-marks\">[3]</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Step-by-Step English Core Solution</div>\n        <div class=\"answer-text\">\n          <p>Dr. Andrew Manson executed a heroic, methodical resuscitation protocol:</p>\n      <ol style=\"margin-left:20px; line-height:1.7;\">\n        <li><strong>Immediate Diagnosis:</strong> Recognizing that the baby's whiteness and limpness indicated <em>asphyxia pallida</em> (lack of oxygen in the blood), he knew standard slapping would not suffice.</li>\n        <li><strong>Clearing Airways:</strong> He wiped mucus from the infant’s nose and mouth to open the respiratory passages.</li>\n        <li><strong>Hydrotherapy Shock Treatment:</strong> He ordered two basins—one filled with water as hot as his hand could bear, the other with ice-cold water. He plunged the limp, slippery body alternately into the cold water, then the steaming water, repeating this thermal shock cycle for fifteen grueling minutes.</li>\n        <li><strong>Vigorous Friction & Chest Compression:</strong> Wrapping the baby in a rough towel, he crushed and released the tiny rib cage rhythmically with his hands, blowing breath into the tiny lungs.</li>\n        <li><strong>The Miracle:</strong> Just as despair gripped the room and the midwife declared it useless, a bubble of mucus issued from the infant’s nostril, the chest convulsed, and the child cried aloud, its skin turning flushed pink.</li>\n      </ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme Rubric (Session 2026–27)</div>\n          \n          <div class=\"marking-row\"><span class=\"marking-key\">Correct identification of asphyxia pallida and clearing of airways</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Alternate hot and cold water immersion shock therapy described</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Rough towel friction, chest compression and successful respiratory revival</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"chapter-nav-btns\" style=\"margin-top:40px; display:flex; justify-content:space-between; align-items:center;\">\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(14)\" style=\"padding:10px 24px; border-radius:8px; border:1px solid #cbd5e1; background:white; font-weight:700; cursor:pointer; color:#334155;\">← Ch 14</button>\n    <a href=\"../ncert-solutions-class-11.html\" class=\"ch-nav-btn next\" style=\"padding:10px 24px; border-radius:8px; border:none; background:#4338ca; color:white; font-weight:700; text-decoration:none;\">Class 11 All Subjects Hub →</a>\n  </div>\n</section>";
